Object.assign(copy.zh, { "add-line-numbers": { principle: "按换行符拆分文本，并从 1 开始为每行添加“数字. ”前缀；空行也计数。", useCase: "在代码评审或会议记录中引用具体行。输入 A、B 两行会得到 1. A、2. B。", troubleshooting: "行数不符时检查空行和末尾换行符。编号属于结果；需要原文时可再移除行号。", faqQuestion: "空行也会编号吗？", faqAnswer: "会。换行拆分出的每个项目都会编号，包括空行；仅含空格的行会保留空格。" } });
Object.assign(copy.es, { "add-line-numbers": { principle: "Divide el texto por saltos de línea y antepone a cada línea un número desde 1 seguido de «. ». También cuenta las líneas vacías.", useCase: "Numera código o actas para señalar una línea concreta. Dos líneas, A y B, producen 1. A y 2. B.", troubleshooting: "Si el total no coincide, revisa las líneas vacías y el salto final. Los números forman parte del resultado; quítalos si necesitas las líneas originales.", faqQuestion: "¿Se numera también una línea vacía?", faqAnswer: "Sí. Se numera cada elemento separado por saltos de línea, incluso si está vacío. Se conservan los espacios de una línea que solo contiene espacios." } });
Object.assign(copy["pt-br"], { "add-line-numbers": { principle: "Divide o texto nas quebras de linha e acrescenta a cada linha um número iniciado em 1, seguido de \". \" Linhas vazias também são contadas.", useCase: "Numere trechos de código ou atas para indicar uma linha específica. Duas linhas, A e B, resultam em 1. A e 2. B.", troubleshooting: "Se a quantidade parecer incorreta, confira as linhas vazias e a quebra final. Os números passam a fazer parte do resultado; remova-os se precisar das linhas originais.", faqQuestion: "Uma linha vazia também recebe número?", faqAnswer: "Sim. Cada item separado por quebras de linha é numerado, inclusive os vazios. Os espaços de uma linha que contém apenas espaços são preservados." } });
Object.assign(copy.de, { "add-line-numbers": { principle: "Teilt den Text an Zeilenumbrüchen und setzt vor jede Zeile eine bei 1 beginnende Nummer mit \". \" Leere Zeilen werden mitgezählt.", useCase: "Nummeriere Codeauszüge oder Besprechungsnotizen, um eine bestimmte Zeile zu referenzieren. Aus den Zeilen A und B werden 1. A und 2. B.", troubleshooting: "Prüfe bei unerwarteter Zeilenzahl leere Zeilen und einen abschließenden Zeilenumbruch. Die Nummern gehören zur Ausgabe; entferne sie bei Bedarf wieder.", faqQuestion: "Erhält eine leere Zeile ebenfalls eine Nummer?", faqAnswer: "Ja. Jedes durch Zeilenumbrüche getrennte Element wird nummeriert, auch leere Zeilen. Leerzeichen in einer nur aus Leerzeichen bestehenden Zeile bleiben erhalten." } });
Object.assign(copy.fr, { "add-line-numbers": { principle: "Découpe le texte aux retours à la ligne et ajoute devant chaque ligne un numéro commençant à 1, suivi de \". \" Les lignes vides sont comptées.", useCase: "Numérote un extrait de code ou un compte rendu pour désigner une ligne précise. Les lignes A et B deviennent 1. A et 2. B.", troubleshooting: "Si le total diffère, vérifiez les lignes vides et le retour final. Les numéros font partie du résultat ; retirez-les si vous avez besoin des lignes d’origine.", faqQuestion: "Une ligne vide reçoit-elle aussi un numéro ?", faqAnswer: "Oui. Chaque élément séparé par un retour est numéroté, même s’il est vide. Les espaces d’une ligne composée uniquement d’espaces sont conservés." } });
Object.assign(copy.vi, { "add-line-numbers": { principle: "Tách văn bản tại dấu xuống dòng rồi thêm số thứ tự bắt đầu từ 1 và \". \" trước mỗi dòng. Dòng trống cũng được tính.", useCase: "Đánh số đoạn mã hoặc biên bản để mọi người nhắc đến đúng dòng. Hai dòng A và B sẽ thành 1. A và 2. B.", troubleshooting: "Nếu số dòng khác dự kiến, hãy kiểm tra dòng trống và dấu xuống dòng cuối. Số thứ tự thuộc kết quả; hãy xóa chúng nếu cần nội dung ban đầu.", faqQuestion: "Dòng trống có được đánh số không?", faqAnswer: "Có. Mỗi mục được tách bằng dấu xuống dòng đều được đánh số, kể cả mục rỗng. Khoảng trắng trong dòng chỉ có dấu cách được giữ nguyên." } });
Object.assign(copy.id, { "add-line-numbers": { principle: "Memisahkan teks pada pergantian baris, lalu memberi nomor mulai dari 1 diikuti \". \" Baris kosong tetap dihitung.", useCase: "Beri nomor pada cuplikan kode atau notulen agar baris tertentu mudah dirujuk. Baris A dan B menjadi 1. A dan 2. B.", troubleshooting: "Jika jumlahnya tidak sesuai, periksa baris kosong dan pergantian baris di bagian akhir. Nomor menjadi bagian hasil; hapus jika ingin baris asli.", faqQuestion: "Apakah baris kosong juga diberi nomor?", faqAnswer: "Ya. Setiap bagian hasil pemisahan baris diberi nomor, termasuk bagian kosong. Spasi pada baris yang hanya berisi spasi tetap dipertahankan." } });
Object.assign(copy.th, { "add-line-numbers": { principle: "แบ่งข้อความตามตัวขึ้นบรรทัดใหม่ แล้วเติมเลขเริ่มจาก 1 และ \". \" ไว้หน้าทุกบรรทัด โดยนับบรรทัดว่างด้วย", useCase: "ใส่เลขให้โค้ดหรือบันทึกการประชุมเพื่ออ้างถึงบรรทัดที่ต้องการ บรรทัด A และ B จะเป็น 1. A และ 2. B", troubleshooting: "หากจำนวนบรรทัดไม่ตรง ให้ตรวจบรรทัดว่างและตัวขึ้นบรรทัดใหม่ท้ายข้อความ เลขเป็นส่วนหนึ่งของผลลัพธ์ หากต้องการต้นฉบับให้ลบเลขภายหลัง", faqQuestion: "บรรทัดว่างจะได้รับเลขด้วยหรือไม่?", faqAnswer: "ได้รับ ทุกส่วนที่แยกด้วยตัวขึ้นบรรทัดใหม่จะถูกใส่เลข รวมถึงบรรทัดว่าง ช่องว่างในบรรทัดที่มีแต่ช่องว่างยังคงอยู่" } });
Object.assign(copy["zh-tw"], { "add-line-numbers": { principle: "依換行符號拆分文字，並從 1 開始在每行前加上「數字. 」；空白行也會計入。", useCase: "在程式碼審查或會議紀錄中標示特定行。A、B 兩行會變成 1. A、2. B。", troubleshooting: "行數不符時，請檢查空白行與最後的換行符號。編號會成為輸出的一部分；需要原文時可再移除。", faqQuestion: "空白行也會編號嗎？", faqAnswer: "會。每個以換行拆分出的項目都會編號，包含空白行；只有空格的行，其空格會保留。" } });
Object.assign(copy.it, { "add-line-numbers": { principle: "Divide il testo alle interruzioni di riga e antepone a ogni riga un numero da 1 seguito da \". \" Anche le righe vuote vengono contate.", useCase: "Numera estratti di codice o verbali per indicare una riga precisa. Le righe A e B diventano 1. A e 2. B.", troubleshooting: "Se il totale non coincide, controlla le righe vuote e l’interruzione finale. I numeri entrano nel risultato; rimuovili se servono le righe originali.", faqQuestion: "Anche una riga vuota riceve un numero?", faqAnswer: "Sì. È numerato ogni elemento separato da un’interruzione, anche se vuoto. Gli spazi di una riga composta solo da spazi vengono mantenuti." } });
Object.assign(copy.nl, { "add-line-numbers": { principle: "Splitst de tekst bij regeleinden en zet voor elke regel een teller vanaf 1 met \". \" Lege regels tellen ook mee.", useCase: "Nummer codefragmenten of notulen zodat je naar een specifieke regel kunt verwijzen. Regels A en B worden 1. A en 2. B.", troubleshooting: "Controleer lege regels en een afsluitende regeleinde als het aantal afwijkt. De nummers worden onderdeel van de uitvoer; verwijder ze als je de oorspronkelijke regels nodig hebt.", faqQuestion: "Krijgt een lege regel ook een nummer?", faqAnswer: "Ja. Elk onderdeel dat door regeleinden ontstaat, krijgt een nummer, ook lege onderdelen. Spaties op een regel met alleen spaties blijven behouden." } });
Object.assign(copy.hi, { "add-line-numbers": { principle: "पाठ को पंक्ति-विराम पर बाँटकर हर पंक्ति के आगे 1 से शुरू होने वाली संख्या और \". \" जोड़ता है। खाली पंक्तियाँ भी गिनी जाती हैं।", useCase: "कोड या बैठक नोट्स को क्रमांकित करें ताकि समीक्षा में किसी पंक्ति का उल्लेख हो सके। A और B पंक्तियाँ 1. A और 2. B बनती हैं।", troubleshooting: "गिनती अलग लगे तो खाली पंक्तियाँ और अंतिम पंक्ति-विराम जाँचें। अंक परिणाम का हिस्सा हैं; मूल पंक्तियाँ चाहिए तो बाद में हटाएँ।", faqQuestion: "क्या खाली पंक्ति को भी संख्या मिलती है?", faqAnswer: "हाँ। पंक्ति-विराम से बने हर हिस्से को क्रमांक मिलता है, खाली हिस्से को भी। केवल रिक्त स्थान वाली पंक्ति के रिक्त स्थान सुरक्षित रहते हैं।" } });
Object.assign(copy.ru, { "add-line-numbers": { principle: "Разбивает текст по переводам строк и добавляет перед каждой номер от 1 и \". \" Пустые строки тоже считаются.", useCase: "Пронумеруйте фрагмент кода или заметки встречи, чтобы сослаться на строку. Строки A и B станут 1. A и 2. B.", troubleshooting: "Если число строк неожиданно, проверьте пустые строки и завершающий перевод. Номера входят в результат; удалите их, если нужны исходные строки.", faqQuestion: "Пустая строка тоже получает номер?", faqAnswer: "Да. Нумеруется каждый элемент, разделённый переводом строки, включая пустой. Пробелы в строке, состоящей только из пробелов, сохраняются." } });
Object.assign(copy.tr, { "add-line-numbers": { principle: "Metni satır sonlarından böler ve her satırın başına 1’den başlayan numara ile \". \" ekler. Boş satırlar da sayılır.", useCase: "Kod parçalarını veya toplantı notlarını numaralandırarak belirli bir satıra gönderme yapın. A ve B satırları 1. A ve 2. B olur.", troubleshooting: "Satır sayısı beklenmiyorsa boş satırları ve sondaki satır sonunu kontrol edin. Numaralar çıktının parçasıdır; özgün satırlar için kaldırın.", faqQuestion: "Boş bir satır da numara alır mı?", faqAnswer: "Evet. Satır sonlarına göre ayrılan her öğe, boş olanlar da dahil, numaralandırılır. Yalnızca boşluk içeren satırdaki boşluklar korunur." } });
Object.assign(copy.pl, { "add-line-numbers": { principle: "Dzieli tekst w miejscach końca wiersza i dodaje przed każdym numer od 1 oraz \". \" Puste wiersze także są liczone.", useCase: "Ponumeruj fragment kodu lub notatki, aby wskazać konkretny wiersz. Wiersze A i B zmienią się w 1. A i 2. B.", troubleshooting: "Jeśli liczba wierszy się nie zgadza, sprawdź puste wiersze i końcowy znak nowej linii. Numery są częścią wyniku; usuń je, jeśli potrzebujesz oryginału.", faqQuestion: "Czy pusty wiersz również dostaje numer?", faqAnswer: "Tak. Numerowany jest każdy element oddzielony znakiem nowej linii, także pusty. Spacje w wierszu zawierającym tylko spacje pozostają bez zmian." } });
Object.assign(copy.fil, { "add-line-numbers": { principle: "Hinahati ang teksto sa mga line break at nilalagyan ang bawat linya ng numerong nagsisimula sa 1 at \". \" Binibilang din ang mga blangkong linya.", useCase: "Lagyan ng numero ang code o tala ng pulong para matukoy ang isang linya sa pagsusuri. Nagiging 1. A at 2. B ang mga linyang A at B.", troubleshooting: "Kung hindi tugma ang bilang, tingnan ang mga blangkong linya at line break sa dulo. Bahagi ng output ang mga numero; alisin ang mga ito kung kailangan ang orihinal.", faqQuestion: "Nilalagyan din ba ng numero ang blangkong linya?", faqAnswer: "Oo. Bawat bahaging nabuo sa paghahati sa line break ay binibigyan ng numero, pati ang blangko. Nananatili ang mga space sa linyang puro space." } });
Object.assign(copy.bn, { "add-line-numbers": { principle: "লাইন ব্রেকে লেখাকে ভাগ করে প্রতিটি লাইনের আগে ১ থেকে শুরু হওয়া সংখ্যা ও \". \" যোগ করে। ফাঁকা লাইনও গণনা করা হয়।", useCase: "কোড বা সভার নোটে নম্বর দিন, যাতে পর্যালোচনায় নির্দিষ্ট লাইন উল্লেখ করা যায়। A ও B লাইন হবে 1. A ও 2. B।", troubleshooting: "লাইন সংখ্যা আলাদা হলে ফাঁকা লাইন এবং শেষের লাইন ব্রেক দেখুন। নম্বর ফলাফলের অংশ; মূল লাইন দরকার হলে পরে সরিয়ে নিন।", faqQuestion: "ফাঁকা লাইনেও কি নম্বর বসে?", faqAnswer: "হ্যাঁ। লাইন ব্রেকে বিভক্ত প্রতিটি অংশে নম্বর বসে, ফাঁকা অংশেও। শুধু স্পেস থাকা লাইনের স্পেস অপরিবর্তিত থাকে।" } });
Object.assign(copy.uk, { "add-line-numbers": { principle: "Розділяє текст за переносами рядків і додає перед кожним номер від 1 та \". \" Порожні рядки також рахуються.", useCase: "Пронумеруйте фрагмент коду або нотатки, щоб указати конкретний рядок під час перевірки. Рядки A і B стануть 1. A та 2. B.", troubleshooting: "Якщо кількість неочікувана, перевірте порожні рядки та завершальний перенос. Номери є частиною результату; видаліть їх, якщо потрібен оригінал.", faqQuestion: "Порожній рядок теж отримує номер?", faqAnswer: "Так. Нумерується кожен елемент, утворений переносами рядків, зокрема порожній. Пробіли в рядку, що містить лише пробіли, зберігаються." } });
Object.assign(copy.ms, { "add-line-numbers": { principle: "Memisahkan teks pada pemisah baris dan meletakkan nombor bermula daripada 1 serta \". \" di hadapan setiap baris. Baris kosong turut dikira.", useCase: "Nomborkan petikan kod atau minit mesyuarat supaya baris tertentu mudah dirujuk. Baris A dan B menjadi 1. A dan 2. B.", troubleshooting: "Jika jumlah baris berbeza, semak baris kosong dan pemisah di hujung teks. Nombor sebahagian daripada hasil; buangkannya jika anda perlukan baris asal.", faqQuestion: "Adakah baris kosong turut menerima nombor?", faqAnswer: "Ya. Setiap bahagian yang dipisahkan oleh pemisah baris dinomborkan, termasuk bahagian kosong. Ruang pada baris yang hanya mengandungi ruang dikekalkan." } });
Object.assign(copy.sv, { "add-line-numbers": { principle: "Delar texten vid radbrytningar och lägger till ett löpnummer från 1 följt av \". \" framför varje rad. Tomma rader räknas också.", useCase: "Numrera kodutdrag eller mötesanteckningar så att en viss rad går att hänvisa till. Raderna A och B blir 1. A och 2. B.", troubleshooting: "Kontrollera tomma rader och en avslutande radbrytning om antalet avviker. Numren ingår i resultatet; ta bort dem om du behöver ursprungsraderna.", faqQuestion: "Får en tom rad också ett nummer?", faqAnswer: "Ja. Varje del som uppstår när texten delas vid radbrytningar numreras, även tomma delar. Blanksteg på en rad som bara innehåller blanksteg bevaras." } });
Object.assign(copy.cs, { "add-line-numbers": { principle: "Rozdělí text podle konců řádků a před každý vloží číslo od 1 následované \". \" Počítají se i prázdné řádky.", useCase: "Očíslujte úryvek kódu nebo zápis, abyste mohli odkázat na konkrétní řádek. Řádky A a B budou 1. A a 2. B.", troubleshooting: "Pokud počet nesedí, zkontrolujte prázdné řádky a koncový konec řádku. Čísla jsou součástí výstupu; odstraňte je, pokud potřebujete původní řádky.", faqQuestion: "Dostane číslo i prázdný řádek?", faqAnswer: "Ano. Čísluje se každá položka oddělená koncem řádku, včetně prázdné. Mezery na řádku tvořeném pouze mezerami zůstávají zachovány." } });
Object.assign(copy.ro, { "add-line-numbers": { principle: "Împarte textul la caracterele de linie nouă și adaugă înaintea fiecărui rând un număr de la 1 urmat de \". \" Sunt numărate și rândurile goale.", useCase: "Numerotează fragmente de cod sau notițe pentru a indica un rând exact. Rândurile A și B devin 1. A și 2. B.", troubleshooting: "Dacă numărul diferă, verifică rândurile goale și caracterul de linie nouă de la final. Numerele fac parte din rezultat; elimină-le dacă ai nevoie de rândurile inițiale.", faqQuestion: "Un rând gol primește și el un număr?", faqAnswer: "Da. Este numerotat fiecare element separat printr-o linie nouă, inclusiv cel gol. Spațiile dintr-un rând format doar din spații sunt păstrate." } });
Object.assign(copy.el, { "add-line-numbers": { principle: "Χωρίζει το κείμενο στις αλλαγές γραμμής και προσθέτει πριν από κάθε γραμμή αριθμό από το 1 και \". \" Μετρώνται και οι κενές γραμμές.", useCase: "Αριθμήστε απόσπασμα κώδικα ή σημειώσεις ώστε να αναφέρετε συγκεκριμένη γραμμή. Οι γραμμές A και B γίνονται 1. A και 2. B.", troubleshooting: "Αν το πλήθος διαφέρει, ελέγξτε τις κενές γραμμές και την τελική αλλαγή. Οι αριθμοί αποτελούν μέρος του αποτελέσματος· αφαιρέστε τους αν χρειάζεστε τις αρχικές γραμμές.", faqQuestion: "Παίρνει αριθμό και μια κενή γραμμή;", faqAnswer: "Ναι. Αριθμείται κάθε στοιχείο που προκύπτει από τον διαχωρισμό στις αλλαγές γραμμής, ακόμη και το κενό. Τα κενά σε γραμμή που περιέχει μόνο κενά διατηρούνται." } });
Object.assign(copy.zh, { "remove-line-numbers": { principle: "在每行开头移除空白、连续数字、可选的句点或右括号以及其后的空白；行中间的数字不会改变。", useCase: "将带编号的文本转成普通行，便于粘贴到不需要列表标记的字段。1. First、2) Second、3 Third 会变成 First、Second、Third。", troubleshooting: "若前缀仍在，检查数字是否位于行首。本工具不解析项目符号、字母编号或句子中的数字，也不会重排或重新编号。", faqQuestion: "像 2024 Plan 这样的标题会保留吗？", faqAnswer: "不会。即使没有句点或括号，行首数字也会被删除，因此 2024 Plan 会变成 Plan。处理数字开头的标题前请检查结果。" } });
Object.assign(copy.es, { "remove-line-numbers": { principle: "Al comienzo de cada línea elimina espacios iniciales, una secuencia de dígitos, un punto o paréntesis de cierre opcional y los espacios siguientes. No cambia los números dentro de la línea.", useCase: "Convierte una lista numerada en líneas simples antes de pegarla en un campo sin marcadores. 1. First, 2) Second y 3 Third quedan como First, Second y Third.", troubleshooting: "Si queda un prefijo, comprueba que los dígitos estén al inicio de la línea. No interpreta viñetas, letras ni números dentro de una frase, y tampoco reordena ni renumera.", faqQuestion: "¿Conservará un título como 2024 Plan?", faqAnswer: "No. Elimina los dígitos iniciales incluso sin punto ni paréntesis; 2024 Plan pasa a ser Plan. Revisa los títulos que empiezan por números." } });
Object.assign(copy["pt-br"], { "remove-line-numbers": { principle: "No início de cada linha, remove espaços, uma sequência de dígitos, um ponto ou parêntese de fechamento opcional e os espaços seguintes. Números no meio da linha não são alterados.", useCase: "Transforme uma lista numerada em linhas simples antes de colá-la em um campo que não deve conter marcadores. 1. First, 2) Second e 3 Third viram First, Second e Third.", troubleshooting: "Se o prefixo continuar, confira se os dígitos estão no início da linha. A ferramenta não interpreta marcadores, letras ou números no meio de frases, nem reordena ou renumera as linhas.", faqQuestion: "Um título como 2024 Plan será preservado?", faqAnswer: "Não. A sequência de dígitos no início é removida mesmo sem ponto ou parêntese; 2024 Plan vira Plan. Confira títulos que começam com números." } });
Object.assign(copy.de, { "remove-line-numbers": { principle: "Entfernt am Zeilenanfang Leerraum, eine Ziffernfolge, optional einen Punkt oder eine schließende Klammer sowie den folgenden Leerraum. Ziffern innerhalb der Zeile bleiben unverändert.", useCase: "Wandle nummerierte Texte in einfache Zeilen um, bevor du sie in ein Feld ohne Listenmarkierungen einfügst. 1. First, 2) Second und 3 Third werden zu First, Second und Third.", troubleshooting: "Prüfe, ob die Ziffern wirklich am Zeilenanfang stehen. Aufzählungszeichen, Buchstaben und Zahlen mitten im Satz werden nicht erkannt; die Zeilen werden weder sortiert noch neu nummeriert.", faqQuestion: "Bleibt ein Titel wie 2024 Plan erhalten?", faqAnswer: "Nein. Führende Ziffern werden auch ohne Punkt oder Klammer entfernt; 2024 Plan wird zu Plan. Kontrolliere Überschriften, die mit einer Zahl beginnen." } });
Object.assign(copy.fr, { "remove-line-numbers": { principle: "Au début de chaque ligne, supprime les espaces initiaux, une suite de chiffres, un point ou une parenthèse fermante facultatifs, puis les espaces suivants. Les chiffres au milieu restent intacts.", useCase: "Convertissez une liste numérotée en lignes simples avant de la coller dans un champ sans marqueurs. 1. First, 2) Second et 3 Third deviennent First, Second et Third.", troubleshooting: "Si un préfixe reste, vérifiez que les chiffres sont bien en début de ligne. L’outil ne traite ni puces, ni lettres, ni nombres au milieu d’une phrase et ne trie pas les lignes.", faqQuestion: "Un titre comme 2024 Plan sera-t-il conservé ?", faqAnswer: "Non. Les chiffres initiaux sont supprimés même sans point ni parenthèse : 2024 Plan devient Plan. Vérifiez les titres qui commencent par un nombre." } });
Object.assign(copy.vi, { "remove-line-numbers": { principle: "Ở đầu mỗi dòng, xóa khoảng trắng, dãy chữ số, dấu chấm hoặc ngoặc đóng tùy chọn và khoảng trắng theo sau. Chữ số giữa dòng không bị đổi.", useCase: "Chuyển danh sách có số thành các dòng thường trước khi dán vào nơi không cần ký hiệu danh sách. 1. First, 2) Second và 3 Third thành First, Second và Third.", troubleshooting: "Nếu tiền tố còn lại, hãy kiểm tra chữ số có nằm ngay đầu dòng không. Công cụ không xử lý dấu đầu dòng, chữ cái đánh số hay số trong câu; cũng không sắp xếp lại dòng.", faqQuestion: "Tiêu đề như 2024 Plan có được giữ nguyên không?", faqAnswer: "Không. Dãy số đầu dòng bị xóa ngay cả khi không có dấu chấm hay ngoặc, nên 2024 Plan thành Plan. Hãy xem lại tiêu đề bắt đầu bằng số." } });
Object.assign(copy.id, { "remove-line-numbers": { principle: "Di awal setiap baris, hapus spasi pembuka, rangkaian angka, titik atau kurung tutup opsional, lalu spasi sesudahnya. Angka di tengah baris tidak berubah.", useCase: "Ubah teks bernomor menjadi baris biasa sebelum ditempel ke kolom yang tidak memerlukan penanda daftar. 1. First, 2) Second, dan 3 Third menjadi First, Second, dan Third.", troubleshooting: "Jika awalan masih ada, pastikan angka berada di awal baris. Alat ini tidak membaca bullet, huruf, atau angka di tengah kalimat, serta tidak mengurutkan ulang baris.", faqQuestion: "Apakah judul seperti 2024 Plan akan tetap utuh?", faqAnswer: "Tidak. Angka di awal dihapus meski tanpa titik atau kurung, sehingga 2024 Plan menjadi Plan. Periksa judul yang dimulai dengan angka." } });
Object.assign(copy.th, { "remove-line-numbers": { principle: "ลบช่องว่างนำหน้า ชุดตัวเลข จุดหรือวงเล็บปิดที่อาจมี และช่องว่างถัดมา ณ ต้นบรรทัด ตัวเลขกลางบรรทัดจะไม่เปลี่ยน", useCase: "เปลี่ยนข้อความที่มีเลขลำดับให้เป็นบรรทัดธรรมดาก่อนวางในช่องที่ไม่ต้องการเครื่องหมายรายการ 1. First, 2) Second และ 3 Third จะเป็น First, Second และ Third", troubleshooting: "หากยังมีคำนำหน้า ให้ตรวจว่าตัวเลขอยู่ต้นบรรทัดจริงหรือไม่ เครื่องมือนี้ไม่แปลความหมายสัญลักษณ์หัวข้อ ตัวอักษร หรือตัวเลขกลางประโยค และไม่เรียงบรรทัดใหม่", faqQuestion: "หัวข้ออย่าง 2024 Plan จะคงเดิมหรือไม่?", faqAnswer: "ไม่คงเดิม ตัวเลขต้นบรรทัดจะถูกลบแม้ไม่มีจุดหรือวงเล็บ ดังนั้น 2024 Plan จะกลายเป็น Plan ควรตรวจหัวข้อที่ขึ้นต้นด้วยตัวเลข" } });
Object.assign(copy["zh-tw"], { "remove-line-numbers": { principle: "在每行開頭移除空白、連續數字、可選的句點或右括號，以及後續空白；行中間的數字不會改變。", useCase: "將編號文字轉成一般行，方便貼到不需要清單標記的欄位。1. First、2) Second、3 Third 會變成 First、Second、Third。", troubleshooting: "若前綴仍在，請確認數字位於行首。本工具不解析項目符號、字母編號或句中的數字，也不會重新排序或編號。", faqQuestion: "像 2024 Plan 這樣的標題會保留嗎？", faqAnswer: "不會。即使沒有句點或括號，行首數字也會被移除，因此 2024 Plan 會變成 Plan。處理數字開頭的標題前請檢查結果。" } });
Object.assign(copy.it, { "remove-line-numbers": { principle: "All’inizio di ogni riga rimuove spazi iniziali, una sequenza di cifre, un punto o una parentesi chiusa facoltativi e gli spazi successivi. Le cifre interne restano invariate.", useCase: "Trasforma un elenco numerato in righe semplici prima di incollarlo in un campo senza marcatori. 1. First, 2) Second e 3 Third diventano First, Second e Third.", troubleshooting: "Se il prefisso resta, verifica che le cifre siano davvero all’inizio della riga. Lo strumento non interpreta elenchi puntati, lettere o numeri interni e non riordina le righe.", faqQuestion: "Un titolo come 2024 Plan rimane intatto?", faqAnswer: "No. Le cifre iniziali vengono rimosse anche senza punto o parentesi: 2024 Plan diventa Plan. Controlla i titoli che iniziano con un numero." } });
Object.assign(copy.nl, { "remove-line-numbers": { principle: "Verwijdert aan het begin van elke regel witruimte, een reeks cijfers, eventueel een punt of sluitende haak en de daaropvolgende witruimte. Cijfers midden in de regel blijven staan.", useCase: "Zet genummerde tekst om in gewone regels voordat je die in een veld zonder lijstmarkeringen plakt. 1. First, 2) Second en 3 Third worden First, Second en Third.", troubleshooting: "Controleer of de cijfers echt aan het begin staan als een voorvoegsel blijft staan. Opsommingstekens, letters en cijfers midden in zinnen worden niet herkend; regels worden niet herschikt.", faqQuestion: "Blijft een titel zoals 2024 Plan behouden?", faqAnswer: "Nee. Begincijfers worden ook zonder punt of haak verwijderd, dus 2024 Plan wordt Plan. Controleer titels die met een getal beginnen." } });
Object.assign(copy.hi, { "remove-line-numbers": { principle: "हर पंक्ति की शुरुआत से रिक्त स्थान, अंकों की शृंखला, वैकल्पिक बिंदु या बंद कोष्ठक और उसके बाद के रिक्त स्थान हटाता है। पंक्ति के बीच के अंक नहीं बदलते।", useCase: "बिना सूची-चिह्न वाले फ़ील्ड में चिपकाने से पहले क्रमांकित पाठ को साधारण पंक्तियों में बदलें। 1. First, 2) Second और 3 Third, First, Second, Third बनते हैं।", troubleshooting: "उपसर्ग बचा हो तो देखें कि अंक सचमुच पंक्ति की शुरुआत में हैं। यह बुलेट, अक्षर-क्रम या वाक्य के बीच के अंकों को नहीं समझता और पंक्तियों को क्रमबद्ध नहीं करता।", faqQuestion: "क्या 2024 Plan जैसा शीर्षक जस का तस रहेगा?", faqAnswer: "नहीं। शुरुआत के अंक बिंदु या कोष्ठक के बिना भी हटते हैं, इसलिए 2024 Plan, Plan बन जाएगा। संख्या से शुरू होने वाले शीर्षक जाँचें।" } });
Object.assign(copy.ru, { "remove-line-numbers": { principle: "В начале каждой строки удаляет пробелы, последовательность цифр, необязательную точку или закрывающую скобку и следующие пробелы. Цифры внутри строки не меняются.", useCase: "Преобразуйте нумерованный текст в обычные строки перед вставкой в поле без маркеров списка. 1. First, 2) Second и 3 Third станут First, Second и Third.", troubleshooting: "Если префикс остался, проверьте, стоят ли цифры в самом начале строки. Маркеры, буквенную нумерацию и числа в середине фразы инструмент не распознаёт и строки не сортирует.", faqQuestion: "Заголовок вроде 2024 Plan останется без изменений?", faqAnswer: "Нет. Начальные цифры удаляются даже без точки или скобки, поэтому 2024 Plan станет Plan. Проверьте заголовки, начинающиеся с числа." } });
Object.assign(copy.tr, { "remove-line-numbers": { principle: "Her satırın başındaki boşlukları, rakam dizisini, isteğe bağlı noktayı veya kapatma parantezini ve ardından gelen boşlukları siler. Satır içindeki rakamlar değişmez.", useCase: "Liste işareti istemeyen bir alana yapıştırmadan önce numaralı metni düz satırlara dönüştürün. 1. First, 2) Second ve 3 Third; First, Second ve Third olur.", troubleshooting: "Önek kalırsa rakamların satırın başında olduğundan emin olun. Madde işaretlerini, harfleri veya cümle içindeki sayıları çözümlemez; satırları sıralamaz ya da yeniden numaralandırmaz.", faqQuestion: "2024 Plan gibi bir başlık aynen kalır mı?", faqAnswer: "Hayır. Başlangıç rakamları nokta veya parantez olmasa da silinir; 2024 Plan, Plan olur. Sayıyla başlayan başlıkları sonucu uygulamadan önce kontrol edin." } });
Object.assign(copy.pl, { "remove-line-numbers": { principle: "Na początku każdego wiersza usuwa spacje, ciąg cyfr, opcjonalną kropkę lub nawias zamykający oraz następujące po nich spacje. Cyfry w środku wiersza pozostają.", useCase: "Zamień numerowany tekst na zwykłe wiersze przed wklejeniem do pola bez oznaczeń listy. 1. First, 2) Second i 3 Third zmienią się w First, Second i Third.", troubleshooting: "Jeśli prefiks pozostaje, sprawdź, czy cyfry rzeczywiście są na początku wiersza. Narzędzie nie rozpoznaje punktorów, liter ani liczb w zdaniu i nie zmienia kolejności wierszy.", faqQuestion: "Czy tytuł taki jak 2024 Plan pozostanie bez zmian?", faqAnswer: "Nie. Początkowy ciąg cyfr jest usuwany nawet bez kropki lub nawiasu, więc 2024 Plan zmieni się w Plan. Sprawdź tytuły zaczynające się od liczby." } });
Object.assign(copy.fil, { "remove-line-numbers": { principle: "Sa simula ng bawat linya, inaalis ang nauunang space, sunod-sunod na digit, opsyonal na tuldok o pansarang panaklong, at kasunod na space. Hindi binabago ang mga digit sa gitna.", useCase: "Gawing payak na mga linya ang numeradong teksto bago idikit sa field na walang list marker. Ang 1. First, 2) Second, at 3 Third ay magiging First, Second, at Third.", troubleshooting: "Kung may prefix pa rin, tiyaking nasa simula talaga ng linya ang mga digit. Hindi nito binibigyang-kahulugan ang bullet, titik, o numerong nasa pangungusap, at hindi nito inaayos muli ang mga linya.", faqQuestion: "Mananatili bang buo ang pamagat na 2024 Plan?", faqAnswer: "Hindi. Tinatanggal ang mga digit sa unahan kahit walang tuldok o panaklong, kaya magiging Plan ang 2024 Plan. Suriin ang mga pamagat na nagsisimula sa numero." } });
Object.assign(copy.bn, { "remove-line-numbers": { principle: "প্রতিটি লাইনের শুরু থেকে ফাঁকা স্থান, পরপর অঙ্ক, ঐচ্ছিক ডট বা বন্ধনী এবং পরের ফাঁকা স্থান সরায়। লাইনের মাঝের অঙ্ক অপরিবর্তিত থাকে।", useCase: "তালিকা চিহ্ন দরকার নেই এমন ঘরে পেস্ট করার আগে নম্বরযুক্ত লেখাকে সাধারণ লাইনে বদলান। 1. First, 2) Second ও 3 Third হবে First, Second ও Third।", troubleshooting: "উপসর্গ থেকে গেলে অঙ্কগুলো লাইনের শুরুতে আছে কি না দেখুন। এটি বুলেট, অক্ষরভিত্তিক নম্বর বা বাক্যের মাঝের অঙ্ক বোঝে না এবং লাইন সাজায় না।", faqQuestion: "2024 Plan-এর মতো শিরোনাম কি অপরিবর্তিত থাকবে?", faqAnswer: "না। ডট বা বন্ধনী না থাকলেও শুরুর অঙ্ক মুছে যায়, তাই 2024 Plan হবে Plan। সংখ্যা দিয়ে শুরু হওয়া শিরোনাম ফলাফলে পরীক্ষা করুন।" } });
Object.assign(copy.uk, { "remove-line-numbers": { principle: "На початку кожного рядка видаляє пробіли, послідовність цифр, необов’язкову крапку або закривну дужку та наступні пробіли. Цифри всередині рядка не змінюються.", useCase: "Перетворіть нумерований текст на звичайні рядки перед вставленням у поле без маркерів списку. 1. First, 2) Second і 3 Third стануть First, Second і Third.", troubleshooting: "Якщо префікс залишився, перевірте, чи цифри стоять на початку рядка. Інструмент не розпізнає маркери, літери чи числа в середині речення та не сортує рядки.", faqQuestion: "Заголовок на кшталт 2024 Plan залишиться без змін?", faqAnswer: "Ні. Початкові цифри видаляються навіть без крапки чи дужки, тож 2024 Plan стане Plan. Перевіряйте заголовки, що починаються з числа." } });
Object.assign(copy.ms, { "remove-line-numbers": { principle: "Pada permulaan setiap baris, buang ruang awal, rangkaian digit, noktah atau kurungan penutup pilihan, serta ruang selepasnya. Digit di tengah baris tidak berubah.", useCase: "Tukarkan teks bernombor kepada baris biasa sebelum menampalnya ke medan tanpa penanda senarai. 1. First, 2) Second dan 3 Third menjadi First, Second dan Third.", troubleshooting: "Jika awalan masih ada, pastikan digit berada di permulaan baris. Alat ini tidak mentafsir bullet, huruf atau nombor dalam ayat dan tidak menyusun semula baris.", faqQuestion: "Adakah tajuk seperti 2024 Plan kekal?", faqAnswer: "Tidak. Digit di awal dibuang walaupun tanpa noktah atau kurungan, jadi 2024 Plan menjadi Plan. Semak tajuk yang bermula dengan nombor." } });
Object.assign(copy.sv, { "remove-line-numbers": { principle: "Tar bort inledande blanksteg, en sifferföljd, en valfri punkt eller slutparentes och efterföljande blanksteg i början av varje rad. Siffror mitt i raden lämnas.", useCase: "Gör numrerad text till vanliga rader innan du klistrar in den i ett fält utan listmarkörer. 1. First, 2) Second och 3 Third blir First, Second och Third.", troubleshooting: "Kontrollera att siffrorna verkligen står först på raden om ett prefix finns kvar. Verktyget tolkar inte punkter, bokstäver eller tal mitt i en mening och sorterar inte raderna.", faqQuestion: "Bevaras en rubrik som 2024 Plan?", faqAnswer: "Nej. Inledande siffror tas bort även utan punkt eller parentes, så 2024 Plan blir Plan. Granska rubriker som börjar med en siffra." } });
Object.assign(copy.cs, { "remove-line-numbers": { principle: "Na začátku každého řádku odstraní počáteční mezery, řadu číslic, případnou tečku nebo uzavírací závorku a následující mezery. Číslice uvnitř řádku nemění.", useCase: "Převeďte číslovaný text na běžné řádky před vložením do pole bez značek seznamu. 1. First, 2) Second a 3 Third budou First, Second a Third.", troubleshooting: "Pokud předpona zůstala, ověřte, že číslice jsou skutečně na začátku řádku. Nástroj nerozpoznává odrážky, písmena ani čísla ve větě a řádky nepřeskupuje.", faqQuestion: "Zůstane nadpis jako 2024 Plan beze změny?", faqAnswer: "Ne. Úvodní číslice se odstraní i bez tečky nebo závorky, takže 2024 Plan bude Plan. Zkontrolujte nadpisy začínající číslem." } });
Object.assign(copy.ro, { "remove-line-numbers": { principle: "La începutul fiecărui rând elimină spațiile inițiale, o secvență de cifre, punctul sau paranteza închisă opțională și spațiile următoare. Cifrele din mijlocul rândului rămân.", useCase: "Transformă textul numerotat în rânduri simple înainte de lipirea într-un câmp fără marcatori de listă. 1. First, 2) Second și 3 Third devin First, Second și Third.", troubleshooting: "Dacă prefixul rămâne, verifică dacă cifrele sunt chiar la începutul rândului. Instrumentul nu interpretează marcatori, litere sau cifre din propoziții și nu reordonează rândurile.", faqQuestion: "Un titlu precum 2024 Plan rămâne neschimbat?", faqAnswer: "Nu. Cifrele inițiale sunt eliminate chiar și fără punct sau paranteză, astfel 2024 Plan devine Plan. Verifică titlurile care încep cu cifre." } });
Object.assign(copy.el, { "remove-line-numbers": { principle: "Στην αρχή κάθε γραμμής αφαιρεί αρχικά κενά, μια ακολουθία ψηφίων, προαιρετική τελεία ή κλείνουσα παρένθεση και τα επόμενα κενά. Τα ψηφία στη μέση της γραμμής μένουν.", useCase: "Μετατρέψτε αριθμημένο κείμενο σε απλές γραμμές πριν το επικολλήσετε σε πεδίο χωρίς δείκτες λίστας. Τα 1. First, 2) Second και 3 Third γίνονται First, Second και Third.", troubleshooting: "Αν παραμένει πρόθεμα, βεβαιωθείτε ότι τα ψηφία βρίσκονται στην αρχή της γραμμής. Δεν αναλύει κουκκίδες, γράμματα ή αριθμούς μέσα σε πρόταση και δεν αναδιατάσσει γραμμές.", faqQuestion: "Θα παραμείνει όπως είναι ένας τίτλος όπως 2024 Plan;", faqAnswer: "Όχι. Τα αρχικά ψηφία αφαιρούνται ακόμη και χωρίς τελεία ή παρένθεση, άρα το 2024 Plan γίνεται Plan. Ελέγξτε τους τίτλους που αρχίζουν με αριθμό." } });
Object.assign(copy.en, { "remove-empty-lines": { principle: "Checks each line after trimming whitespace and drops it only when nothing remains. Lines with text keep their original leading and trailing spaces; internal spacing is untouched.", useCase: "Clean pasted notes that gained blank or whitespace-only rows without collapsing the separation inside sentences. The lines A, blank, spaces-only, B reduce to A and B on separate lines.", troubleshooting: "A row containing tabs or spaces is treated as empty and removed. If you want to keep a paragraph gap, add the desired line break back after processing.", faqQuestion: "Does this tool trim indentation from nonempty lines?", faqAnswer: "No. Trimming is used only to decide whether a line is empty. A line that contains text is copied unchanged, including its indentation." } });
Object.assign(copy.ja, { "remove-empty-lines": { principle: "各行を trim して空かどうかを判定し、何も残らない行だけを削除します。文字のある行の前後の空白や、行内の連続スペースは変更しません。", useCase: "コピーしたメモに空行や空白だけの行が増えたとき、文章を保ったまま取り除けます。A、空行、空白だけの行、B は、A と B の二行になります。", troubleshooting: "タブやスペースだけの行も空行として削除されます。段落間に一行残したい場合は、処理後に必要な改行を加えてください。", faqQuestion: "文字がある行のインデントも削除されますか？", faqAnswer: "いいえ。trim は空行かどうかの判定にだけ使います。文字を含む行は前後の空白も含めてそのまま残ります。" } });
Object.assign(copy.zh, { "remove-empty-lines": { principle: "逐行检查 trim 后是否还有内容，只删除结果为空的行。含文字的行及其首尾空格保持原样，行内空格不会合并。", useCase: "清理复制笔记时多出的空行或仅含空白的行，同时保留句子内容。A、空行、空格行、B 最后只剩 A 和 B 两行。", troubleshooting: "只含制表符或空格的行也会被视为空行删除。若段落间需要留一行，请在处理后自行补回换行。", faqQuestion: "非空行的缩进也会删除吗？", faqAnswer: "不会。trim 只用于判断该行是否为空。含有内容的行会原样保留，包括开头和结尾的空格。" } });
Object.assign(copy.es, { "remove-empty-lines": { principle: "Evalúa cada línea tras aplicar trim y elimina solo las que no contienen nada. Las líneas con texto conservan sus espacios iniciales y finales; no se compactan los espacios internos.", useCase: "Limpia notas copiadas que acumularon líneas vacías o con espacios sin alterar el texto. Las líneas A, vacía, solo espacios y B quedan como A y B en líneas separadas.", troubleshooting: "Una línea con tabuladores o espacios también se considera vacía. Si necesitas dejar un salto entre párrafos, vuelve a añadirlo después del proceso.", faqQuestion: "¿También elimina la sangría de las líneas con contenido?", faqAnswer: "No. trim solo se usa para decidir si una línea está vacía. Las líneas con texto se copian sin cambios, incluida su sangría." } });
Object.assign(copy["pt-br"], { "remove-empty-lines": { principle: "Verifica cada linha após trim e remove somente as que ficam sem conteúdo. Linhas com texto mantêm os espaços iniciais e finais; espaços internos não são compactados.", useCase: "Limpe anotações coladas que ganharam linhas vazias ou com espaços, sem alterar o texto. As linhas A, vazia, só com espaços e B ficam como A e B em linhas separadas.", troubleshooting: "Uma linha com tabulações ou espaços também é considerada vazia. Se quiser manter um intervalo entre parágrafos, adicione a quebra necessária depois do processamento.", faqQuestion: "A indentação de linhas com conteúdo também é removida?", faqAnswer: "Não. trim serve apenas para decidir se a linha está vazia. Uma linha com texto é copiada sem alterações, incluindo a indentação." } });
Object.assign(copy.de, { "remove-empty-lines": { principle: "Prüft jede Zeile nach trim und entfernt nur Zeilen, bei denen nichts übrig bleibt. Zeilen mit Text behalten ihre führenden und nachfolgenden Leerzeichen; innere Abstände werden nicht zusammengefasst.", useCase: "Bereinige eingefügte Notizen mit leeren oder nur aus Leerraum bestehenden Zeilen, ohne den Text zu verändern. Aus A, leerer Zeile, Leerraumzeile und B bleiben A und B auf getrennten Zeilen.", troubleshooting: "Auch eine Zeile mit Tabs oder Leerzeichen gilt als leer und wird entfernt. Soll zwischen Absätzen eine Lücke bleiben, füge den gewünschten Zeilenumbruch danach wieder ein.", faqQuestion: "Wird die Einrückung von Zeilen mit Inhalt entfernt?", faqAnswer: "Nein. trim dient nur zur Prüfung, ob eine Zeile leer ist. Zeilen mit Text werden einschließlich ihrer Einrückung unverändert übernommen." } });
Object.assign(copy.fr, { "remove-empty-lines": { principle: "Évalue chaque ligne après trim et supprime uniquement celles qui ne contiennent plus rien. Les lignes avec du texte gardent leurs espaces de début et de fin ; les espaces internes ne sont pas réduits.", useCase: "Nettoyez des notes copiées qui contiennent des lignes vides ou composées d’espaces, sans modifier le texte. Les lignes A, vide, espaces seuls et B deviennent A et B sur deux lignes.", troubleshooting: "Une ligne contenant des tabulations ou des espaces est également considérée comme vide. Pour conserver un intervalle entre paragraphes, réinsérez le saut souhaité après le traitement.", faqQuestion: "L’indentation des lignes non vides est-elle supprimée ?", faqAnswer: "Non. trim sert uniquement à vérifier si une ligne est vide. Une ligne contenant du texte est recopiée telle quelle, indentation comprise." } });
Object.assign(copy.vi, { "remove-empty-lines": { principle: "Kiểm tra từng dòng sau khi trim và chỉ bỏ dòng không còn ký tự nào. Dòng có nội dung giữ nguyên khoảng trắng đầu cuối; khoảng trắng bên trong không bị gộp.", useCase: "Dọn ghi chú đã dán có thêm dòng trống hoặc chỉ chứa khoảng trắng mà không sửa phần chữ. Các dòng A, trống, chỉ có dấu cách, B còn lại A và B trên hai dòng.", troubleshooting: "Dòng chỉ có tab hoặc dấu cách cũng được xem là trống và bị xóa. Nếu cần khoảng cách giữa đoạn, hãy thêm lại dấu xuống dòng mong muốn sau khi xử lý.", faqQuestion: "Công cụ có xóa thụt lề của dòng có chữ không?", faqAnswer: "Không. trim chỉ dùng để xác định dòng trống. Dòng có nội dung được sao chép nguyên trạng, kể cả phần thụt lề." } });
Object.assign(copy.id, { "remove-empty-lines": { principle: "Memeriksa setiap baris setelah trim dan hanya membuang baris yang tidak menyisakan isi. Baris berteks mempertahankan spasi awal dan akhir; spasi di dalamnya tidak dirapatkan.", useCase: "Bersihkan catatan tempel yang memiliki baris kosong atau hanya berisi spasi tanpa mengubah teks. Baris A, kosong, spasi saja, B akan tersisa sebagai A dan B pada baris terpisah.", troubleshooting: "Baris yang hanya berisi tab atau spasi juga dianggap kosong dan dihapus. Jika jarak antarparagraf perlu dipertahankan, tambahkan kembali baris kosong setelah pemrosesan.", faqQuestion: "Apakah indentasi pada baris berisi teks ikut dihapus?", faqAnswer: "Tidak. trim hanya dipakai untuk memeriksa apakah sebuah baris kosong. Baris berisi teks disalin apa adanya, termasuk indentasinya." } });
Object.assign(copy.th, { "remove-empty-lines": { principle: "ตรวจแต่ละบรรทัดหลัง trim แล้วลบเฉพาะบรรทัดที่ไม่เหลือเนื้อหา บรรทัดที่มีข้อความจะคงช่องว่างหัวท้าย และไม่รวมช่องว่างภายใน", useCase: "ล้างบันทึกที่คัดลอกมาซึ่งมีบรรทัดว่างหรือบรรทัดที่มีแต่ช่องว่าง โดยไม่เปลี่ยนข้อความ บรรทัด A, ว่าง, ช่องว่างล้วน, B จะเหลือ A และ B คนละบรรทัด", troubleshooting: "บรรทัดที่มีแต่แท็บหรือช่องว่างก็ถือว่าว่างและถูกลบ หากต้องการเว้นระหว่างย่อหน้า ให้เพิ่มบรรทัดใหม่ตามต้องการหลังประมวลผล", faqQuestion: "เครื่องมือลบการเยื้องของบรรทัดที่มีข้อความหรือไม่?", faqAnswer: "ไม่ trim ใช้เพียงตรวจว่าบรรทัดว่างหรือไม่ บรรทัดที่มีข้อความจะถูกคัดลอกเหมือนเดิม รวมถึงการเยื้อง" } });
Object.assign(copy["zh-tw"], { "remove-empty-lines": { principle: "逐行檢查 trim 後是否還有內容，只刪除結果為空的行。含文字的行及其前後空格會保留，行內空格不會合併。", useCase: "清除複製筆記時多出的空白行或僅含空格的行，同時保留文字。A、空行、空格行、B 最後只剩 A 與 B 兩行。", troubleshooting: "只有定位字元或空格的行也會視為空行刪除。若段落間需要保留間隔，請在處理後自行補回換行。", faqQuestion: "非空行的縮排也會刪除嗎？", faqAnswer: "不會。trim 只用來判斷該行是否為空。含有內容的行會原樣保留，包括前後空格。" } });
Object.assign(copy.it, { "remove-empty-lines": { principle: "Controlla ogni riga dopo trim e rimuove solo quelle che non contengono più nulla. Le righe con testo conservano gli spazi iniziali e finali; gli spazi interni non vengono compressi.", useCase: "Pulisci appunti incollati con righe vuote o composte da spazi senza modificare il testo. Le righe A, vuota, solo spazi e B diventano A e B su righe separate.", troubleshooting: "Anche una riga con tabulazioni o spazi viene considerata vuota. Se vuoi mantenere una separazione tra paragrafi, aggiungi l’interruzione desiderata dopo l’elaborazione.", faqQuestion: "Viene rimossa anche l’indentazione delle righe con testo?", faqAnswer: "No. trim serve solo a stabilire se una riga è vuota. Le righe con testo vengono copiate senza modifiche, inclusa l’indentazione." } });
Object.assign(copy.nl, { "remove-empty-lines": { principle: "Controleert elke regel na trim en verwijdert alleen regels waar niets overblijft. Regels met tekst behouden hun voor- en achterspaties; interne spaties worden niet samengevoegd.", useCase: "Ruim geplakte notities met lege of alleen uit witruimte bestaande regels op zonder de tekst te veranderen. Van A, leeg, alleen spaties en B blijven A en B op aparte regels over.", troubleshooting: "Een regel met alleen tabs of spaties geldt ook als leeg en wordt verwijderd. Voeg na verwerking een regeleinde toe als je ruimte tussen alinea’s wilt behouden.", faqQuestion: "Verwijdert dit ook de inspringing van regels met tekst?", faqAnswer: "Nee. trim wordt alleen gebruikt om te bepalen of een regel leeg is. Regels met tekst worden ongewijzigd gekopieerd, inclusief inspringing." } });
Object.assign(copy.hi, { "remove-empty-lines": { principle: "हर पंक्ति पर trim के बाद जाँचता है और केवल वही पंक्ति हटाता है जिसमें कुछ नहीं बचता। पाठ वाली पंक्तियों के आगे-पीछे के रिक्त स्थान और आंतरिक spacing जस की तस रहती है।", useCase: "कॉपी किए नोट्स की खाली या केवल रिक्त स्थान वाली पंक्तियाँ हटाएँ, बिना पाठ बदले। A, खाली, केवल spaces, B वाली पंक्तियों में अंततः A और B अलग पंक्तियों पर रहते हैं।", troubleshooting: "केवल tab या spaces वाली पंक्ति भी खाली मानी जाती है। अनुच्छेदों के बीच अंतर चाहिए तो प्रक्रिया के बाद इच्छित line break वापस जोड़ें।", faqQuestion: "क्या यह सामग्री वाली पंक्ति का indentation हटाता है?", faqAnswer: "नहीं। trim केवल खाली होने की जाँच के लिए है। पाठ वाली पंक्ति indentation सहित अपरिवर्तित कॉपी होती है।" } });
Object.assign(copy.ru, { "remove-empty-lines": { principle: "Проверяет каждую строку после trim и удаляет только ту, в которой ничего не осталось. Начальные и конечные пробелы строк с текстом сохраняются; внутренние пробелы не объединяются.", useCase: "Уберите пустые строки и строки только с пробелами из скопированных заметок, не меняя текст. Из строк A, пустой, пробельной и B останутся A и B на отдельных строках.", troubleshooting: "Строка только с табуляцией или пробелами тоже считается пустой. Если между абзацами нужен интервал, добавьте нужный перевод строки после обработки.", faqQuestion: "Удаляется ли отступ у непустых строк?", faqAnswer: "Нет. trim используется лишь для проверки пустоты строки. Строка с текстом копируется без изменений, включая отступ." } });
Object.assign(copy.tr, { "remove-empty-lines": { principle: "Her satırı trim sonrasında denetler ve yalnızca içeriği kalmayan satırları siler. Metinli satırların başındaki ve sonundaki boşluklar korunur; iç boşluklar birleştirilmez.", useCase: "Kopyalanan notlardaki boş veya yalnızca boşluk içeren satırları metni değiştirmeden temizleyin. A, boş, yalnızca boşluk ve B satırlarından ayrı satırlarda A ve B kalır.", troubleshooting: "Yalnızca sekme veya boşluk içeren satırlar da boş sayılarak silinir. Paragraflar arasında boşluk istiyorsanız işlemden sonra gerekli satır sonunu ekleyin.", faqQuestion: "Metin içeren satırların girintisi de silinir mi?", faqAnswer: "Hayır. trim yalnızca satırın boş olup olmadığını belirler. Metin içeren satır girintisiyle birlikte olduğu gibi kopyalanır." } });
Object.assign(copy.pl, { "remove-empty-lines": { principle: "Sprawdza każdy wiersz po trim i usuwa tylko te, w których nic nie pozostaje. Wiersze z tekstem zachowują początkowe i końcowe spacje; odstępy wewnątrz nie są łączone.", useCase: "Usuń puste lub zawierające wyłącznie białe znaki wiersze ze skopiowanych notatek bez zmiany tekstu. Z wierszy A, pustego, ze spacjami i B pozostaną A oraz B w osobnych wierszach.", troubleshooting: "Wiersz zawierający tylko tabulatory lub spacje również jest pusty i zostanie usunięty. Jeśli odstęp między akapitami ma pozostać, dodaj odpowiedni znak nowej linii po przetworzeniu.", faqQuestion: "Czy narzędzie usuwa wcięcia z wierszy z tekstem?", faqAnswer: "Nie. trim służy wyłącznie do sprawdzenia, czy wiersz jest pusty. Wiersze z tekstem są kopiowane bez zmian, także z wcięciami." } });
Object.assign(copy.fil, { "remove-empty-lines": { principle: "Sinusuri ang bawat linya pagkatapos ng trim at inaalis lamang ang walang natitirang laman. Pinananatili ang puwang sa unahan at hulihan ng linyang may teksto; hindi pinagsasama ang mga puwang sa loob.", useCase: "Alisin ang blangko o puro whitespace na linya sa kinopyang tala nang hindi binabago ang teksto. Sa mga linyang A, blangko, puro space, B, A at B na lang ang matitira sa magkahiwalay na linya.", troubleshooting: "Itinuturing ding blangko ang linyang puro tab o space at inaalis ito. Kung kailangan ng pagitan ng talata, idagdag muli ang gustong line break pagkatapos iproseso.", faqQuestion: "Inaalis ba ang indent ng linyang may nilalaman?", faqAnswer: "Hindi. Ginagamit lang ang trim para malaman kung blangko ang linya. Kinokopya nang walang pagbabago ang linyang may teksto, kasama ang indent nito." } });
Object.assign(copy.bn, { "remove-empty-lines": { principle: "প্রতিটি লাইনে trim করার পর কিছু থাকে কি না দেখে; কিছু না থাকলেই শুধু লাইনটি সরায়। লেখাযুক্ত লাইনের শুরুর ও শেষের স্পেস থাকে, আর ভেতরের স্পেস এক করা হয় না।", useCase: "কপি করা নোটের ফাঁকা বা শুধু স্পেস থাকা লাইন সরিয়ে লেখাটি অক্ষত রাখুন। A, ফাঁকা, স্পেস-শুধু, B লাইনের শেষে আলাদা লাইনে A ও B থাকে।", troubleshooting: "শুধু ট্যাব বা স্পেস থাকা লাইনও ফাঁকা বলে মুছে যায়। অনুচ্ছেদের মাঝে ফাঁক রাখতে চাইলে প্রক্রিয়ার পরে প্রয়োজনীয় লাইন ব্রেক যোগ করুন।", faqQuestion: "লেখাযুক্ত লাইনের indentation কি মুছে যায়?", faqAnswer: "না। trim শুধু লাইন ফাঁকা কি না যাচাই করে। লেখাযুক্ত লাইন indentation-সহ অপরিবর্তিত কপি হয়।" } });
Object.assign(copy.uk, { "remove-empty-lines": { principle: "Перевіряє кожен рядок після trim і видаляє лише той, у якому нічого не залишилося. Початкові та кінцеві пробіли рядків із текстом зберігаються; внутрішні пробіли не стискаються.", useCase: "Приберіть порожні рядки та рядки лише з пробілами зі скопійованих нотаток, не змінюючи текст. Із рядків A, порожнього, пробільного та B залишаться A і B окремо.", troubleshooting: "Рядок лише з табуляцією або пробілами також вважається порожнім. Якщо потрібен проміжок між абзацами, додайте потрібний перенос після обробки.", faqQuestion: "Чи видаляється відступ у рядках із текстом?", faqAnswer: "Ні. trim використовується лише для визначення порожнього рядка. Рядки з текстом копіюються без змін, разом із відступом." } });
Object.assign(copy.ms, { "remove-empty-lines": { principle: "Memeriksa setiap baris selepas trim dan membuang hanya baris yang tiada kandungan. Baris berteks mengekalkan ruang di awal dan akhir; ruang di dalam tidak dirapatkan.", useCase: "Bersihkan nota yang ditampal daripada baris kosong atau baris yang hanya mengandungi ruang tanpa mengubah teks. Daripada baris A, kosong, ruang sahaja dan B, A serta B kekal pada baris berasingan.", troubleshooting: "Baris yang hanya mengandungi tab atau ruang turut dianggap kosong lalu dibuang. Jika mahu jarak antara perenggan, tambahkan semula pemisah baris selepas pemprosesan.", faqQuestion: "Adakah inden baris berteks turut dibuang?", faqAnswer: "Tidak. trim hanya digunakan untuk menentukan sama ada baris kosong. Baris yang mengandungi teks disalin tanpa perubahan, termasuk inden." } });
Object.assign(copy.sv, { "remove-empty-lines": { principle: "Kontrollerar varje rad efter trim och tar bara bort rader där inget återstår. Rader med text behåller blanksteg i början och slutet; mellanliggande blanksteg slås inte ihop.", useCase: "Rensa inklistrade anteckningar från tomma rader eller rader med enbart blanksteg utan att ändra texten. Av raderna A, tom, bara blanksteg och B återstår A och B på varsin rad.", troubleshooting: "En rad med enbart tabbar eller blanksteg räknas också som tom och tas bort. Lägg tillbaka önskad radbrytning efteråt om ett mellanrum mellan stycken ska finnas kvar.", faqQuestion: "Tas indrag bort från rader som innehåller text?", faqAnswer: "Nej. trim används endast för att avgöra om raden är tom. Rader med text kopieras oförändrade, inklusive indrag." } });
Object.assign(copy.cs, { "remove-empty-lines": { principle: "Po trim zkontroluje každý řádek a odstraní jen ten, ve kterém nic nezůstalo. Řádky s textem si zachovají počáteční i koncové mezery; vnitřní mezery se neslučují.", useCase: "Vyčistěte vložené poznámky od prázdných řádků a řádků tvořených mezerami, aniž změníte text. Z řádků A, prázdný, mezery a B zůstanou A a B na samostatných řádcích.", troubleshooting: "Řádek tvořený pouze tabulátory nebo mezerami se také odstraní. Chcete-li zachovat mezeru mezi odstavci, přidejte po zpracování potřebný konec řádku.", faqQuestion: "Odstraní se i odsazení řádků s textem?", faqAnswer: "Ne. trim slouží pouze k určení, zda je řádek prázdný. Řádky s textem se kopírují beze změny včetně odsazení." } });
Object.assign(copy.ro, { "remove-empty-lines": { principle: "Verifică fiecare rând după trim și îl elimină numai dacă nu mai conține nimic. Rândurile cu text își păstrează spațiile de la început și sfârșit; spațiile interne nu sunt comasate.", useCase: "Curăță notițele lipite de rânduri goale sau formate doar din spații fără a schimba textul. Din rândurile A, gol, doar spații și B rămân A și B pe linii separate.", troubleshooting: "Un rând cu doar taburi sau spații este considerat gol și eliminat. Dacă vrei să păstrezi distanța dintre paragrafe, adaugă la loc linia dorită după procesare.", faqQuestion: "Se elimină indentarea rândurilor cu text?", faqAnswer: "Nu. trim este folosit doar pentru a decide dacă rândul este gol. Rândurile cu text sunt copiate neschimbate, inclusiv indentarea." } });
Object.assign(copy.el, { "remove-empty-lines": { principle: "Ελέγχει κάθε γραμμή μετά το trim και αφαιρεί μόνο όσες δεν έχουν περιεχόμενο. Οι γραμμές με κείμενο διατηρούν τα αρχικά και τελικά κενά· τα εσωτερικά κενά δεν συμπτύσσονται.", useCase: "Καθαρίστε αντιγραμμένες σημειώσεις από κενές γραμμές ή γραμμές μόνο με κενά χωρίς αλλαγή του κειμένου. Από τις γραμμές A, κενή, μόνο κενά και B μένουν οι A και B χωριστά.", troubleshooting: "Γραμμή μόνο με tab ή κενά θεωρείται επίσης κενή και αφαιρείται. Αν χρειάζεστε διάστημα ανάμεσα στις παραγράφους, προσθέστε ξανά την αλλαγή γραμμής μετά την επεξεργασία.", faqQuestion: "Αφαιρείται η εσοχή από γραμμές που έχουν κείμενο;", faqAnswer: "Όχι. Το trim χρησιμοποιείται μόνο για να διαπιστωθεί αν μια γραμμή είναι κενή. Οι γραμμές με κείμενο αντιγράφονται ως έχουν, μαζί με την εσοχή." } });
Object.assign(copy.en, { "remove-characters": { principle: "The selected mode removes digits, ASCII letters, precomposed Hangul syllables, or characters that are not Unicode letters, numbers, or whitespace. Custom mode removes every occurrence of the literal text in the second input.", useCase: "Strip digits from an identifier such as A12-B3 to get A-B, or remove a repeated separator with custom mode. Choose the mode that matches the characters you intend to keep.", troubleshooting: "Check the selected mode and, for custom removal, the exact second-input string. The Hangul option covers precomposed syllables only; decomposed Jamo may remain. Special-character mode preserves letters, numbers, and whitespace.", faqQuestion: "Does Hangul mode remove every Korean character?", faqAnswer: "No. It targets the precomposed syllable range U+AC00–U+D7AF. Separate initial, medial, or final Jamo are outside that range and can remain in the result." } });
Object.assign(copy.ja, { "remove-characters": { principle: "選択モードに応じて数字、ASCII英字、完成形ハングル音節、またはUnicodeの文字・数字・空白以外を削除します。カスタムモードは2つ目の入力欄の文字列をすべて削除します。", useCase: "A12-B3 の数字を除いて A-B にしたり、カスタムモードで繰り返し使われる区切り文字を取り除いたりできます。残したい文字に合うモードを選んでください。", troubleshooting: "選択中のモードと、カスタム削除なら2つ目の入力欄を確認してください。ハングルモードは完成形音節だけが対象で、分解された字母は残る場合があります。記号モードでは文字・数字・空白を保持します。", faqQuestion: "ハングルモードですべての韓国語文字を削除できますか？", faqAnswer: "いいえ。対象は完成形音節の範囲 U+AC00–U+D7AF です。分離した初声・中声・終声の字母は範囲外のため残ることがあります。" } });
Object.assign(copy.zh, { "remove-characters": { principle: "所选模式可删除数字、ASCII 英文字母、预组韩文音节，或 Unicode 字母、数字、空白以外的字符。自定义模式会删除第二个输入框中字符串的所有出现位置。", useCase: "从 A12-B3 中去掉数字得到 A-B，或用自定义模式移除重复分隔符。请按要删除的字符选择模式。", troubleshooting: "检查所选模式；自定义删除时还要核对第二个输入框的完整字符串。韩文模式只覆盖预组音节，分解的韩文字母可能保留。特殊字符模式会保留字母、数字和空白。", faqQuestion: "韩文模式会删除所有韩文字母吗？", faqAnswer: "不会。它只删除 U+AC00–U+D7AF 范围内的预组音节。分离的初声、中声或终声字母不在此范围内，可能留在结果中。" } });
Object.assign(copy.es, { "remove-characters": { principle: "El modo elegido elimina dígitos, letras ASCII, sílabas Hangul precompuestas o caracteres que no sean letras, números ni espacios Unicode. El modo personalizado elimina todas las apariciones del texto del segundo campo.", useCase: "Quita los dígitos de A12-B3 para obtener A-B, o elimina un separador repetido con el modo personalizado. Elige el modo según los caracteres que quieras retirar.", troubleshooting: "Comprueba el modo seleccionado y, en el modo personalizado, el texto exacto del segundo campo. Hangul solo cubre sílabas precompuestas; los jamo descompuestos pueden quedar. El modo de símbolos conserva letras, números y espacios.", faqQuestion: "¿El modo Hangul elimina todos los caracteres coreanos?", faqAnswer: "No. Solo abarca las sílabas precompuestas U+AC00–U+D7AF. Los jamo iniciales, mediales o finales separados quedan fuera del rango y pueden permanecer." } });
Object.assign(copy["pt-br"], { "remove-characters": { principle: "O modo escolhido remove dígitos, letras ASCII, sílabas Hangul precompostas ou caracteres que não sejam letras, números ou espaços Unicode. O modo personalizado remove todas as ocorrências do texto informado no segundo campo.", useCase: "Remova os dígitos de A12-B3 para obter A-B ou use o modo personalizado para apagar um separador repetido. Escolha o modo conforme os caracteres que deseja retirar.", troubleshooting: "Confira o modo escolhido e, no modo personalizado, o texto exato do segundo campo. Hangul abrange apenas sílabas precompostas; jamo separados podem permanecer. O modo de símbolos preserva letras, números e espaços.", faqQuestion: "O modo Hangul remove todos os caracteres coreanos?", faqAnswer: "Não. Ele cobre somente sílabas precompostas no intervalo U+AC00–U+D7AF. Jamo iniciais, mediais ou finais separados ficam fora desse intervalo e podem continuar no resultado." } });
Object.assign(copy.de, { "remove-characters": { principle: "Der gewählte Modus entfernt Ziffern, ASCII-Buchstaben, zusammengesetzte Hangul-Silben oder Zeichen, die keine Unicode-Buchstaben, Zahlen oder Leerzeichen sind. Der benutzerdefinierte Modus entfernt jedes Vorkommen des Textes aus dem zweiten Eingabefeld.", useCase: "Entferne Ziffern aus A12-B3, um A-B zu erhalten, oder lösche mit dem benutzerdefinierten Modus ein wiederkehrendes Trennzeichen. Wähle den Modus passend zu den zu entfernenden Zeichen.", troubleshooting: "Prüfe den Modus und bei benutzerdefiniertem Entfernen den genauen Text im zweiten Feld. Hangul umfasst nur zusammengesetzte Silben; zerlegte Jamo können bleiben. Der Sonderzeichenmodus erhält Buchstaben, Zahlen und Leerraum.", faqQuestion: "Entfernt der Hangul-Modus alle koreanischen Zeichen?", faqAnswer: "Nein. Er erfasst nur zusammengesetzte Silben im Bereich U+AC00–U+D7AF. Getrennte Anfangs-, Mittel- oder End-Jamo liegen außerhalb dieses Bereichs und können erhalten bleiben." } });
Object.assign(copy.fr, { "remove-characters": { principle: "Le mode choisi supprime les chiffres, les lettres ASCII, les syllabes Hangul précomposées ou les caractères qui ne sont ni lettres Unicode, ni nombres, ni espaces. Le mode personnalisé supprime toutes les occurrences du texte du second champ.", useCase: "Retirez les chiffres de A12-B3 pour obtenir A-B, ou utilisez le mode personnalisé pour enlever un séparateur répété. Choisissez le mode correspondant aux caractères à supprimer.", troubleshooting: "Vérifiez le mode choisi et, en mode personnalisé, le contenu exact du second champ. Hangul ne couvre que les syllabes précomposées ; les jamo décomposés peuvent rester. Le mode symboles conserve lettres, nombres et espaces.", faqQuestion: "Le mode Hangul supprime-t-il tous les caractères coréens ?", faqAnswer: "Non. Il cible uniquement les syllabes précomposées U+AC00–U+D7AF. Les jamo initiaux, médians ou finaux séparés sont hors de cette plage et peuvent rester." } });
Object.assign(copy.vi, { "remove-characters": { principle: "Chế độ được chọn xóa chữ số, chữ Latin ASCII, âm tiết Hangul dựng sẵn hoặc ký tự không thuộc nhóm chữ cái, số và khoảng trắng Unicode. Chế độ tùy chỉnh xóa mọi lần xuất hiện của chuỗi trong ô nhập thứ hai.", useCase: "Xóa số trong A12-B3 để còn A-B, hoặc dùng chế độ tùy chỉnh để bỏ dấu phân cách lặp lại. Chọn chế độ phù hợp với nhóm ký tự cần xóa.", troubleshooting: "Kiểm tra chế độ đang chọn và chuỗi chính xác ở ô thứ hai nếu dùng tùy chỉnh. Chế độ Hangul chỉ bao gồm âm tiết dựng sẵn; jamo tách rời có thể còn lại. Chế độ ký tự đặc biệt giữ chữ, số và khoảng trắng.", faqQuestion: "Chế độ Hangul có xóa mọi ký tự tiếng Hàn không?", faqAnswer: "Không. Chế độ này chỉ nhắm đến âm tiết dựng sẵn trong khoảng U+AC00–U+D7AF. Jamo đầu, giữa hoặc cuối tách rời nằm ngoài khoảng đó nên có thể còn lại." } });
Object.assign(copy.id, { "remove-characters": { principle: "Mode terpilih menghapus digit, huruf ASCII, suku kata Hangul prakomposisi, atau karakter selain huruf, angka, dan spasi Unicode. Mode khusus menghapus semua kemunculan teks pada masukan kedua.", useCase: "Hapus digit dari A12-B3 untuk memperoleh A-B, atau gunakan mode khusus untuk menghilangkan pemisah yang berulang. Pilih mode sesuai karakter yang ingin dibuang.", troubleshooting: "Periksa mode yang dipilih dan teks persis pada masukan kedua untuk mode khusus. Mode Hangul hanya mencakup suku kata prakomposisi; jamo terurai dapat tersisa. Mode karakter khusus mempertahankan huruf, angka, dan spasi.", faqQuestion: "Apakah mode Hangul menghapus semua karakter Korea?", faqAnswer: "Tidak. Mode ini hanya mencakup suku kata prakomposisi U+AC00–U+D7AF. Jamo awal, tengah, atau akhir yang terpisah berada di luar rentang itu dan dapat tetap ada." } });
Object.assign(copy.th, { "remove-characters": { principle: "โหมดที่เลือกจะลบตัวเลข ตัวอักษรละติน ASCII พยางค์ฮันกึลสำเร็จรูป หรืออักขระที่ไม่ใช่ตัวอักษร ตัวเลข หรือช่องว่าง Unicode โหมดกำหนดเองจะลบข้อความในช่องที่สองทุกตำแหน่ง", useCase: "ลบตัวเลขจาก A12-B3 ให้เหลือ A-B หรือใช้โหมดกำหนดเองเพื่อลบตัวคั่นที่ซ้ำ เลือกโหมดให้ตรงกับอักขระที่ต้องการลบ", troubleshooting: "ตรวจโหมดที่เลือก และตรวจข้อความในช่องที่สองหากใช้โหมดกำหนดเอง โหมดฮันกึลครอบคลุมเฉพาะพยางค์สำเร็จรูป จาโมที่แยกอาจเหลืออยู่ โหมดสัญลักษณ์พิเศษจะเก็บตัวอักษร ตัวเลข และช่องว่าง", faqQuestion: "โหมดฮันกึลลบอักขระเกาหลีทั้งหมดหรือไม่?", faqAnswer: "ไม่ ลบเฉพาะพยางค์สำเร็จรูปช่วง U+AC00–U+D7AF จาโมต้น กลาง หรือท้ายที่แยกกันอยู่นอกช่วงนี้และอาจยังคงอยู่" } });
Object.assign(copy["zh-tw"], { "remove-characters": { principle: "所選模式會刪除數字、ASCII 英文字母、預組韓文字音節，或非 Unicode 字母、數字與空白的字元。自訂模式會移除第二個輸入欄中文字串的所有出現處。", useCase: "從 A12-B3 移除數字得到 A-B，或用自訂模式刪除重複的分隔字元。請依要刪除的字元選擇模式。", troubleshooting: "確認所選模式；使用自訂模式時也要核對第二個欄位的完整字串。韓文模式只涵蓋預組音節，分解的字母可能保留。特殊字元模式會保留字母、數字與空白。", faqQuestion: "韓文模式會移除所有韓文字元嗎？", faqAnswer: "不會。它只處理 U+AC00–U+D7AF 範圍內的預組音節。分離的初聲、中聲或終聲字母不在範圍內，因此可能留下。" } });
Object.assign(copy.it, { "remove-characters": { principle: "La modalità scelta rimuove cifre, lettere ASCII, sillabe Hangul precomposte o caratteri che non sono lettere Unicode, numeri o spazi. La modalità personalizzata elimina ogni occorrenza del testo nel secondo campo.", useCase: "Rimuovi le cifre da A12-B3 per ottenere A-B oppure usa la modalità personalizzata per eliminare un separatore ripetuto. Scegli la modalità in base ai caratteri da togliere.", troubleshooting: "Controlla la modalità e, per la rimozione personalizzata, il testo esatto nel secondo campo. Hangul comprende solo sillabe precomposte; i jamo separati possono restare. La modalità simboli conserva lettere, numeri e spazi.", faqQuestion: "La modalità Hangul rimuove tutti i caratteri coreani?", faqAnswer: "No. Interessa solo le sillabe precomposte nell’intervallo U+AC00–U+D7AF. I jamo iniziali, mediani o finali separati sono fuori intervallo e possono rimanere." } });
Object.assign(copy.nl, { "remove-characters": { principle: "De gekozen modus verwijdert cijfers, ASCII-letters, vooraf samengestelde Hangul-lettergrepen of tekens die geen Unicode-letter, getal of witruimte zijn. De aangepaste modus verwijdert elke voorkoming van de tekst in het tweede invoerveld.", useCase: "Verwijder cijfers uit A12-B3 om A-B over te houden, of wis een herhaald scheidingsteken met de aangepaste modus. Kies de modus die past bij de tekens die weg moeten.", troubleshooting: "Controleer de gekozen modus en bij aangepaste verwijdering de exacte tekst in het tweede veld. Hangul omvat alleen vooraf samengestelde lettergrepen; losse jamo kunnen blijven staan. De symboolmodus behoudt letters, cijfers en witruimte.", faqQuestion: "Verwijdert de Hangul-modus alle Koreaanse tekens?", faqAnswer: "Nee. Alleen vooraf samengestelde lettergrepen in U+AC00–U+D7AF worden verwijderd. Losse begin-, midden- of eind-jamo vallen buiten dat bereik en kunnen blijven staan." } });
Object.assign(copy.hi, { "remove-characters": { principle: "चुना गया मोड अंक, ASCII अक्षर, पहले से जुड़े Hangul syllable या Unicode अक्षर, संख्या और whitespace के अलावा के चिह्न हटाता है। कस्टम मोड दूसरे इनपुट में दिए पाठ की हर आवृत्ति हटाता है।", useCase: "A12-B3 से अंक हटाकर A-B पाएँ, या कस्टम मोड से बार-बार आने वाला separator हटाएँ। हटाए जाने वाले अक्षरों के अनुसार मोड चुनें।", troubleshooting: "चुना हुआ मोड और कस्टम हटाने पर दूसरे इनपुट का ठीक पाठ जाँचें। Hangul मोड केवल precomposed syllable हटाता है; अलग jamo रह सकते हैं। विशेष-चिह्न मोड अक्षर, अंक और whitespace रखता है।", faqQuestion: "क्या Hangul मोड सभी कोरियाई अक्षर हटाता है?", faqAnswer: "नहीं। यह केवल U+AC00–U+D7AF की precomposed syllable range पर काम करता है। अलग शुरुआती, मध्य या अंतिम jamo इस सीमा से बाहर हैं और रह सकते हैं।" } });
Object.assign(copy.ru, { "remove-characters": { principle: "Выбранный режим удаляет цифры, ASCII-буквы, составленные слоги хангыль или символы, не являющиеся буквами Unicode, числами и пробелами. Пользовательский режим удаляет все вхождения текста из второго поля.", useCase: "Удалите цифры из A12-B3, чтобы получить A-B, или уберите повторяющийся разделитель пользовательским режимом. Выберите категорию символов, которую нужно убрать.", troubleshooting: "Проверьте выбранный режим и точную строку во втором поле для пользовательской замены. Режим хангыль охватывает только составленные слоги; отдельные джамо могут остаться. Режим спецсимволов сохраняет буквы, числа и пробелы.", faqQuestion: "Удаляет ли режим хангыль все корейские знаки?", faqAnswer: "Нет. Он затрагивает только составленные слоги U+AC00–U+D7AF. Раздельные начальные, срединные или конечные джамо находятся вне диапазона и могут сохраниться." } });
Object.assign(copy.tr, { "remove-characters": { principle: "Seçilen mod rakamları, ASCII harflerini, önceden birleştirilmiş Hangul hecelerini veya Unicode harf, sayı ve boşluk olmayan karakterleri siler. Özel mod ikinci girdideki metnin tüm eşleşmelerini kaldırır.", useCase: "A12-B3 içindeki rakamları silip A-B elde edin ya da yinelenen bir ayırıcıyı özel modla kaldırın. Silinecek karakterlere uygun modu seçin.", troubleshooting: "Seçili modu ve özel silme için ikinci alandaki metni kontrol edin. Hangul modu yalnızca önceden birleştirilmiş heceleri kapsar; ayrık jamo kalabilir. Özel karakter modu harfleri, sayıları ve boşlukları korur.", faqQuestion: "Hangul modu tüm Korece karakterleri siler mi?", faqAnswer: "Hayır. Yalnızca U+AC00–U+D7AF aralığındaki önceden birleştirilmiş heceleri hedefler. Ayrı başlangıç, orta veya son jamo bu aralığın dışında olduğundan kalabilir." } });
Object.assign(copy.pl, { "remove-characters": { principle: "Wybrany tryb usuwa cyfry, litery ASCII, złożone sylaby Hangul albo znaki niebędące literami Unicode, cyframi ani białymi znakami. Tryb własny usuwa każde wystąpienie tekstu z drugiego pola.", useCase: "Usuń cyfry z A12-B3, aby otrzymać A-B, lub skasuj powtarzający się separator w trybie własnym. Wybierz tryb zgodny ze znakami do usunięcia.", troubleshooting: "Sprawdź wybrany tryb, a w trybie własnym także dokładny tekst drugiego pola. Hangul obejmuje tylko złożone sylaby; rozdzielone jamo mogą pozostać. Tryb znaków specjalnych zachowuje litery, cyfry i odstępy.", faqQuestion: "Czy tryb Hangul usuwa wszystkie znaki koreańskie?", faqAnswer: "Nie. Obejmuje wyłącznie złożone sylaby z zakresu U+AC00–U+D7AF. Oddzielne jamo początkowe, środkowe lub końcowe leżą poza tym zakresem i mogą pozostać." } });
Object.assign(copy.fil, { "remove-characters": { principle: "Inaalis ng napiling mode ang digit, ASCII letter, precomposed Hangul syllable, o mga character na hindi Unicode letter, number, o whitespace. Inaalis ng custom mode ang lahat ng paglitaw ng tekstong nasa ikalawang input.", useCase: "Alisin ang mga digit sa A12-B3 para maging A-B, o burahin ang paulit-ulit na separator gamit ang custom mode. Piliin ang mode ayon sa mga character na aalisin.", troubleshooting: "Tingnan ang napiling mode at ang eksaktong teksto sa ikalawang input para sa custom removal. Precomposed syllable lang ang saklaw ng Hangul; maaaring maiwan ang magkakahiwalay na jamo. Pinananatili ng special-character mode ang mga titik, numero, at whitespace.", faqQuestion: "Inaalis ba ng Hangul mode ang lahat ng Korean character?", faqAnswer: "Hindi. Ang precomposed syllable lang sa saklaw na U+AC00–U+D7AF ang tinatarget nito. Nasa labas nito ang magkakahiwalay na initial, medial, o final jamo kaya maaaring manatili." } });
Object.assign(copy.bn, { "remove-characters": { principle: "নির্বাচিত মোড অঙ্ক, ASCII অক্ষর, precomposed Hangul syllable বা Unicode অক্ষর, সংখ্যা ও whitespace নয় এমন চিহ্ন সরায়। কাস্টম মোড দ্বিতীয় ইনপুটের লেখার প্রতিটি উপস্থিতি মুছে দেয়।", useCase: "A12-B3 থেকে অঙ্ক সরিয়ে A-B পান, অথবা কাস্টম মোডে বারবার থাকা বিভাজক মুছুন। কোন অক্ষর সরাতে চান সেই অনুযায়ী মোড বেছে নিন।", troubleshooting: "নির্বাচিত মোড এবং কাস্টম ব্যবহারে দ্বিতীয় ইনপুটের সঠিক লেখা দেখুন। Hangul মোড শুধু precomposed syllable ধরে; আলাদা jamo থেকে যেতে পারে। বিশেষ চিহ্নের মোড অক্ষর, সংখ্যা ও whitespace রাখে।", faqQuestion: "Hangul মোড কি সব কোরীয় অক্ষর মুছে দেয়?", faqAnswer: "না। এটি শুধু U+AC00–U+D7AF সীমার precomposed syllable সরায়। আলাদা প্রাথমিক, মধ্য বা শেষ jamo এই সীমার বাইরে, তাই থেকে যেতে পারে।" } });
Object.assign(copy.uk, { "remove-characters": { principle: "Вибраний режим видаляє цифри, ASCII-літери, складені склади хангиль або символи, що не є літерами Unicode, числами чи пробілами. Власний режим видаляє всі входження тексту з другого поля.", useCase: "Приберіть цифри з A12-B3, щоб отримати A-B, або видаліть повторюваний роздільник власним режимом. Оберіть режим за потрібною категорією символів.", troubleshooting: "Перевірте вибраний режим і точний текст другого поля для власного видалення. Режим хангиль охоплює лише складені склади; окремі джамо можуть лишитися. Режим спецсимволів зберігає літери, цифри й пробіли.", faqQuestion: "Чи видаляє режим хангиль усі корейські символи?", faqAnswer: "Ні. Він охоплює лише складені склади U+AC00–U+D7AF. Окремі початкові, середні або кінцеві джамо поза цим діапазоном можуть лишитися." } });
Object.assign(copy.ms, { "remove-characters": { principle: "Mod yang dipilih membuang digit, huruf ASCII, suku kata Hangul prabentuk atau aksara yang bukan huruf Unicode, nombor atau ruang putih. Mod tersuai membuang setiap kemunculan teks dalam input kedua.", useCase: "Buang digit daripada A12-B3 untuk mendapatkan A-B, atau padam pemisah berulang dengan mod tersuai. Pilih mod mengikut aksara yang mahu dibuang.", troubleshooting: "Semak mod pilihan dan teks tepat dalam input kedua bagi mod tersuai. Mod Hangul hanya meliputi suku kata prabentuk; jamo terurai mungkin kekal. Mod simbol khas mengekalkan huruf, nombor dan ruang putih.", faqQuestion: "Adakah mod Hangul membuang semua aksara Korea?", faqAnswer: "Tidak. Ia hanya menyasarkan suku kata prabentuk dalam julat U+AC00–U+D7AF. Jamo awal, tengah atau akhir yang terpisah berada di luar julat dan mungkin kekal." } });
Object.assign(copy.sv, { "remove-characters": { principle: "Det valda läget tar bort siffror, ASCII-bokstäver, förkomponerade Hangul-stavelser eller tecken som inte är Unicode-bokstäver, siffror eller blanksteg. Anpassat läge tar bort varje förekomst av texten i det andra fältet.", useCase: "Ta bort siffrorna i A12-B3 för att få A-B, eller radera en återkommande avgränsare med anpassat läge. Välj läge efter vilka tecken som ska bort.", troubleshooting: "Kontrollera valt läge och den exakta texten i det andra fältet vid anpassad borttagning. Hangul-läget omfattar bara förkomponerade stavelser; separata jamo kan finnas kvar. Specialteckenläget behåller bokstäver, siffror och blanksteg.", faqQuestion: "Tar Hangul-läget bort alla koreanska tecken?", faqAnswer: "Nej. Det gäller endast förkomponerade stavelser i intervallet U+AC00–U+D7AF. Separata initiala, mediala eller finala jamo ligger utanför intervallet och kan finnas kvar." } });
Object.assign(copy.cs, { "remove-characters": { principle: "Zvolený režim odstraní číslice, znaky ASCII, předkomponované slabiky Hangul nebo znaky, které nejsou písmeny Unicode, čísly ani mezerami. Vlastní režim odstraní každý výskyt textu z druhého pole.", useCase: "Odstraňte číslice z A12-B3 a získáte A-B, nebo vlastním režimem smažte opakovaný oddělovač. Vyberte režim podle znaků, které chcete odstranit.", troubleshooting: "Zkontrolujte zvolený režim a u vlastního odstranění přesný text ve druhém poli. Režim Hangul zahrnuje jen předkomponované slabiky; rozložené jamo mohou zůstat. Režim speciálních znaků zachovává písmena, čísla a mezery.", faqQuestion: "Odstraní režim Hangul všechny korejské znaky?", faqAnswer: "Ne. Cílí jen na předkomponované slabiky U+AC00–U+D7AF. Oddělená počáteční, prostřední nebo koncová jamo leží mimo tento rozsah a mohou zůstat." } });
Object.assign(copy.ro, { "remove-characters": { principle: "Modul ales elimină cifre, litere ASCII, silabe Hangul precompuse sau caractere care nu sunt litere Unicode, numere ori spații. Modul personalizat elimină toate aparițiile textului din al doilea câmp.", useCase: "Elimină cifrele din A12-B3 pentru a obține A-B sau șterge un separator repetat cu modul personalizat. Alege modul în funcție de caracterele vizate.", troubleshooting: "Verifică modul ales și textul exact din al doilea câmp pentru eliminarea personalizată. Hangul acoperă doar silabe precompuse; jamo descompuse pot rămâne. Modul pentru simboluri păstrează litere, cifre și spații.", faqQuestion: "Modul Hangul elimină toate caracterele coreene?", faqAnswer: "Nu. Vizează doar silabele precompuse U+AC00–U+D7AF. Jamo inițiale, mediale sau finale separate sunt în afara intervalului și pot rămâne." } });
Object.assign(copy.el, { "remove-characters": { principle: "Η επιλεγμένη λειτουργία αφαιρεί ψηφία, γράμματα ASCII, προδιαμορφωμένες συλλαβές Hangul ή χαρακτήρες που δεν είναι γράμματα Unicode, αριθμοί ή κενά. Η προσαρμοσμένη λειτουργία αφαιρεί κάθε εμφάνιση του κειμένου στο δεύτερο πεδίο.", useCase: "Αφαιρέστε τα ψηφία από το A12-B3 για να μείνει A-B ή διαγράψτε επαναλαμβανόμενο διαχωριστικό με την προσαρμοσμένη λειτουργία. Επιλέξτε τη σωστή κατηγορία.", troubleshooting: "Ελέγξτε τη λειτουργία και το ακριβές κείμενο του δεύτερου πεδίου για προσαρμοσμένη αφαίρεση. Το Hangul καλύπτει μόνο προδιαμορφωμένες συλλαβές· διαχωρισμένα jamo μπορεί να μείνουν. Η λειτουργία συμβόλων διατηρεί γράμματα, αριθμούς και κενά.", faqQuestion: "Η λειτουργία Hangul αφαιρεί όλους τους κορεατικούς χαρακτήρες;", faqAnswer: "Όχι. Στοχεύει μόνο προδιαμορφωμένες συλλαβές U+AC00–U+D7AF. Ξεχωριστά αρχικά, μεσαία ή τελικά jamo είναι εκτός εύρους και μπορεί να παραμείνουν." } });
Object.assign(copy.en, { "text-repeater": { principle: "Copies the input string an integer number of times and joins the copies with the selected separator. The count is clamped to 1–1,000. The size guard checks input length multiplied by count; separator length is not included.", useCase: "Build a repeatable test pattern or a sample with delimiters. With input ha, count 3, and separator -, the output is ha-ha-ha.", troubleshooting: "Check the count and separator if the result differs from what you expected. Counts above 1,000 are capped; a repeated input length over 1,000,000 triggers an error. A long separator can make the final output longer than that checked input total.", faqQuestion: "Is the complete output always limited to 1,000,000 characters?", faqAnswer: "The guard rejects an input-string length multiplied by the count above 1,000,000. It does not include separators in that calculation, so a long separator can make the joined output exceed that figure." } });
Object.assign(copy.ja, { "text-repeater": { principle: "入力文字列を整数回分並べ、選択した区切り文字で連結します。回数は1～1,000に調整されます。サイズ確認は入力文字列の長さ×回数で行い、区切り文字の長さは含みません。", useCase: "テスト用の繰り返しパターンや区切り付きのサンプルを作れます。入力 ha、回数3、区切り文字 - なら ha-ha-ha になります。", troubleshooting: "結果が想定と違う場合は回数と区切り文字を確認してください。1,000を超える回数は上限に調整され、入力文字列の合計が1,000,000を超えるとエラーになります。長い区切り文字は最終結果をさらに長くします。", faqQuestion: "最終結果全体は必ず1,000,000文字以下ですか？", faqAnswer: "入力文字列の長さ×回数が1,000,000を超える場合にエラーになります。この計算には区切り文字の長さを含まないため、長い区切り文字を使うと最終結果が上限を超えることがあります。" } });
Object.assign(copy.zh, { "text-repeater": { principle: "将输入字符串复制指定的整数次数，并用所选分隔符连接。次数限制在 1–1,000。长度检查按输入长度×次数计算，不包含分隔符长度。", useCase: "快速生成重复测试样本或带分隔符的文本。输入 ha、次数 3、分隔符 -，结果为 ha-ha-ha。", troubleshooting: "结果不符时检查次数和分隔符。超过 1,000 的次数会按上限处理；重复输入本身超过 1,000,000 个字符会报错。较长的分隔符还会增加最终结果长度。", faqQuestion: "最终输出一定不超过 1,000,000 个字符吗？", faqAnswer: "程序会拦截输入字符串长度×次数超过 1,000,000 的情况。计算不包含分隔符，因此分隔符较长时，最终拼接结果可能超过该数值。" } });
Object.assign(copy.es, { "text-repeater": { principle: "Repite la cadena de entrada un número entero de veces y une las copias con el separador elegido. La cantidad se limita a 1–1.000. El control de tamaño calcula la longitud de entrada por la cantidad y no incluye el separador.", useCase: "Crea un patrón de prueba repetible o una muestra delimitada. Con el texto ha, cantidad 3 y separador -, el resultado es ha-ha-ha.", troubleshooting: "Si el resultado difiere, revisa la cantidad y el separador. Las cantidades superiores a 1.000 se limitan; si el texto repetido supera 1.000.000 de unidades, aparece un error. Un separador largo puede aumentar más el resultado final.", faqQuestion: "¿La salida completa siempre queda por debajo de 1.000.000 de caracteres?", faqAnswer: "El límite rechaza una longitud del texto de entrada multiplicada por la cantidad superior a 1.000.000. No suma el separador, así que uno largo puede hacer que la salida final supere esa cifra." } });
Object.assign(copy["pt-br"], { "text-repeater": { principle: "Repete a cadeia de entrada um número inteiro de vezes e une as cópias com o separador escolhido. A quantidade fica entre 1 e 1.000. A verificação calcula o tamanho do texto multiplicado pela quantidade e não inclui o separador.", useCase: "Crie um padrão de teste repetível ou uma amostra com delimitadores. Com o texto ha, quantidade 3 e separador -, o resultado é ha-ha-ha.", troubleshooting: "Se o resultado divergir, confira a quantidade e o separador. Valores acima de 1.000 são limitados; se o texto repetido ultrapassar 1.000.000 de unidades, ocorre um erro. Um separador longo pode aumentar ainda mais a saída final.", faqQuestion: "A saída completa sempre fica abaixo de 1.000.000 de caracteres?", faqAnswer: "O limite rejeita texto de entrada multiplicado pela quantidade acima de 1.000.000. O separador não entra nessa conta, então um separador longo pode fazer o resultado final ultrapassar esse valor." } });
Object.assign(copy.de, { "text-repeater": { principle: "Wiederholt die Eingabe eine ganzzahlige Anzahl von Malen und verbindet die Kopien mit dem gewählten Trennzeichen. Die Anzahl wird auf 1 bis 1.000 begrenzt. Die Größenprüfung berechnet Eingabelänge × Anzahl; das Trennzeichen zählt dabei nicht mit.", useCase: "Erzeuge ein wiederholbares Testmuster oder ein Beispiel mit Trennzeichen. Bei Eingabe ha, Anzahl 3 und Trennzeichen - lautet das Ergebnis ha-ha-ha.", troubleshooting: "Prüfe Anzahl und Trennzeichen, wenn das Ergebnis abweicht. Werte über 1.000 werden begrenzt; überschreitet der wiederholte Eingabetext 1.000.000 Einheiten, erscheint ein Fehler. Ein langes Trennzeichen kann die endgültige Ausgabe zusätzlich verlängern.", faqQuestion: "Ist die gesamte Ausgabe immer auf 1.000.000 Zeichen begrenzt?", faqAnswer: "Abgewiesen wird eine Eingabelänge × Anzahl über 1.000.000. Das Trennzeichen wird nicht mitgerechnet; bei einem langen Trennzeichen kann die verbundene Ausgabe daher länger sein." } });
Object.assign(copy.fr, { "text-repeater": { principle: "Répète la chaîne d’entrée un nombre entier de fois et relie les copies avec le séparateur choisi. Le nombre est limité à 1–1 000. Le contrôle calcule longueur d’entrée × nombre, sans compter la longueur du séparateur.", useCase: "Créez un motif de test répétable ou un exemple avec séparateurs. Avec le texte ha, le nombre 3 et le séparateur -, le résultat est ha-ha-ha.", troubleshooting: "Vérifiez le nombre et le séparateur si le résultat diffère. Au-delà de 1 000, le nombre est plafonné ; un texte répété dépassant 1 000 000 d’unités déclenche une erreur. Un séparateur long peut encore allonger le résultat final.", faqQuestion: "La sortie complète reste-t-elle toujours sous 1 000 000 caractères ?", faqAnswer: "La limite bloque une longueur d’entrée multipliée par le nombre supérieure à 1 000 000. Le séparateur n’est pas inclus dans ce calcul ; un séparateur long peut donc faire dépasser ce total à la sortie assemblée." } });
Object.assign(copy.vi, { "text-repeater": { principle: "Lặp chuỗi đầu vào theo số nguyên lần và nối các bản sao bằng dấu phân cách đã chọn. Số lần được giới hạn trong 1–1.000. Kiểm tra kích thước tính độ dài đầu vào × số lần, không tính độ dài dấu phân cách.", useCase: "Tạo mẫu kiểm thử lặp lại hoặc chuỗi có dấu phân cách. Với đầu vào ha, số lần 3 và dấu phân cách -, kết quả là ha-ha-ha.", troubleshooting: "Nếu kết quả khác dự kiến, hãy kiểm tra số lần và dấu phân cách. Số lần trên 1.000 bị giới hạn; phần văn bản lặp vượt 1.000.000 đơn vị sẽ báo lỗi. Dấu phân cách dài có thể làm kết quả cuối dài hơn nữa.", faqQuestion: "Toàn bộ kết quả có luôn dưới 1.000.000 ký tự không?", faqAnswer: "Bộ kiểm tra chặn khi độ dài chuỗi đầu vào nhân số lần vượt 1.000.000. Phép tính không gồm dấu phân cách, nên dấu phân cách dài có thể khiến kết quả ghép vượt con số đó." } });
Object.assign(copy.id, { "text-repeater": { principle: "Mengulang string masukan sebanyak bilangan bulat dan menggabungkan salinannya dengan pemisah pilihan. Jumlah dibatasi 1–1.000. Pemeriksaan ukuran menghitung panjang masukan × jumlah, tanpa memasukkan panjang pemisah.", useCase: "Buat pola uji berulang atau contoh dengan pembatas. Dengan masukan ha, jumlah 3, dan pemisah -, hasilnya ha-ha-ha.", troubleshooting: "Periksa jumlah dan pemisah jika hasil berbeda. Jumlah di atas 1.000 dibatasi; teks yang diulang melebihi 1.000.000 unit akan memicu kesalahan. Pemisah panjang dapat menambah panjang hasil akhir.", faqQuestion: "Apakah seluruh hasil selalu dibatasi 1.000.000 karakter?", faqAnswer: "Pemeriksaan menolak panjang teks masukan dikalikan jumlah yang melebihi 1.000.000. Pemisah tidak ikut dihitung, sehingga pemisah panjang dapat membuat hasil gabungan melewati angka tersebut." } });
Object.assign(copy.th, { "text-repeater": { principle: "ทำซ้ำข้อความตามจำนวนเต็มแล้วเชื่อมสำเนาด้วยตัวคั่นที่เลือก จำนวนถูกจำกัดไว้ที่ 1–1,000 การตรวจขนาดคำนวณความยาวข้อความต้นฉบับ×จำนวน โดยไม่รวมความยาวตัวคั่น", useCase: "สร้างรูปแบบทดสอบซ้ำหรือข้อความตัวอย่างที่มีตัวคั่น เมื่อใช้ ha จำนวน 3 และตัวคั่น - ผลลัพธ์คือ ha-ha-ha", troubleshooting: "หากผลลัพธ์ไม่ตรง ให้ตรวจจำนวนและตัวคั่น จำนวนเกิน 1,000 จะถูกจำกัด และข้อความต้นฉบับที่ทำซ้ำเกิน 1,000,000 หน่วยจะเกิดข้อผิดพลาด ตัวคั่นยาวอาจทำให้ผลลัพธ์จริงยาวขึ้นอีก", faqQuestion: "ผลลัพธ์สุดท้ายทั้งหมดจำกัดไม่เกิน 1,000,000 อักขระเสมอหรือไม่?", faqAnswer: "ระบบปฏิเสธเมื่อความยาวข้อความต้นฉบับ×จำนวนเกิน 1,000,000 แต่ไม่ได้รวมตัวคั่น ดังนั้นตัวคั่นที่ยาวอาจทำให้ผลลัพธ์ที่ต่อแล้วเกินตัวเลขนี้" } });
Object.assign(copy["zh-tw"], { "text-repeater": { principle: "將輸入字串重複指定的整數次，並以所選分隔符連接。次數限制為 1–1,000。長度檢查以輸入長度×次數計算，不含分隔符長度。", useCase: "快速建立可重複的測試樣本或含分隔符的字串。輸入 ha、次數 3、分隔符 -，結果為 ha-ha-ha。", troubleshooting: "結果不符時請檢查次數與分隔符。超過 1,000 次會採用上限；重複輸入本身超過 1,000,000 個字元會報錯。較長的分隔符會再增加最終結果長度。", faqQuestion: "最終輸出一定不超過 1,000,000 個字元嗎？", faqAnswer: "程式會阻擋輸入字串長度×次數超過 1,000,000 的情況。計算不含分隔符，因此分隔符較長時，串接結果仍可能超過此數值。" } });
Object.assign(copy.it, { "text-repeater": { principle: "Ripete la stringa di input un numero intero di volte e unisce le copie con il separatore scelto. Il conteggio è limitato a 1–1.000. Il controllo calcola lunghezza dell’input × conteggio, senza includere il separatore.", useCase: "Crea un modello di test ripetibile o un esempio con delimitatori. Con input ha, conteggio 3 e separatore -, il risultato è ha-ha-ha.", troubleshooting: "Se il risultato differisce, controlla conteggio e separatore. I valori oltre 1.000 vengono limitati; il testo ripetuto oltre 1.000.000 di unità genera un errore. Un separatore lungo può allungare ulteriormente l’output finale.", faqQuestion: "L’intero output è sempre limitato a 1.000.000 di caratteri?", faqAnswer: "Il controllo blocca lunghezza dell’input × conteggio oltre 1.000.000. Il separatore non è incluso, quindi un separatore lungo può far superare tale valore al risultato concatenato." } });
Object.assign(copy.nl, { "text-repeater": { principle: "Herhaalt de invoertekst een geheel aantal keren en verbindt de kopieën met het gekozen scheidingsteken. Het aantal wordt beperkt tot 1–1.000. De lengtetest berekent invoerlengte × aantal en telt het scheidingsteken niet mee.", useCase: "Maak een herhaalbaar testpatroon of voorbeeld met scheidingstekens. Met invoer ha, aantal 3 en scheidingsteken - wordt het resultaat ha-ha-ha.", troubleshooting: "Controleer aantal en scheidingsteken als de uitvoer afwijkt. Waarden boven 1.000 worden begrensd; herhaalde invoertekst boven 1.000.000 eenheden geeft een fout. Een lang scheidingsteken kan de uiteindelijke uitvoer verder verlengen.", faqQuestion: "Is de volledige uitvoer altijd maximaal 1.000.000 tekens?", faqAnswer: "De controle blokkeert invoerlengte × aantal boven 1.000.000. Het scheidingsteken telt niet mee, dus met een lang scheidingsteken kan de samengevoegde uitvoer langer worden." } });
Object.assign(copy.hi, { "text-repeater": { principle: "इनपुट स्ट्रिंग को पूर्णांक संख्या में दोहराकर चुने गए separator से जोड़ता है। गिनती 1–1,000 तक सीमित है। आकार जाँच input length × count देखती है; separator की लंबाई इसमें नहीं जुड़ती।", useCase: "दोहराने योग्य test pattern या delimiter वाला नमूना बनाएँ। ha इनपुट, गिनती 3 और - separator से ha-ha-ha मिलता है।", troubleshooting: "परिणाम अलग हो तो गिनती और separator जाँचें। 1,000 से बड़ी गिनती सीमित होती है; दोहराया गया इनपुट 1,000,000 units से बड़ा हो तो त्रुटि आती है। लंबा separator अंतिम परिणाम को और बढ़ा सकता है।", faqQuestion: "क्या पूरा परिणाम हमेशा 1,000,000 characters से कम रहता है?", faqAnswer: "जाँच तब रोकती है जब input length × count 1,000,000 से अधिक हो। separator इस गणना में शामिल नहीं है, इसलिए लंबा separator जोड़ने पर अंतिम परिणाम इस संख्या से बड़ा हो सकता है।" } });
Object.assign(copy.ru, { "text-repeater": { principle: "Повторяет входную строку целое число раз и соединяет копии выбранным разделителем. Число повторов ограничено диапазоном 1–1 000. Проверка размера считает длину ввода × число повторов, не учитывая разделитель.", useCase: "Создайте повторяющийся тестовый шаблон или образец с разделителями. Для ввода ha, числа 3 и разделителя - результат будет ha-ha-ha.", troubleshooting: "Если результат не совпадает с ожиданием, проверьте число повторов и разделитель. Значения выше 1 000 ограничиваются; повторённый текст длиннее 1 000 000 единиц вызывает ошибку. Длинный разделитель дополнительно увеличит итог.", faqQuestion: "Весь итог всегда ограничен 1 000 000 символов?", faqAnswer: "Проверка отклоняет длину входной строки, умноженную на число повторов, если она превышает 1 000 000. Разделитель не учитывается, поэтому длинный разделитель может увеличить итог сверх этого значения." } });
Object.assign(copy.tr, { "text-repeater": { principle: "Girdi metnini tam sayı kadar tekrarlar ve kopyaları seçilen ayırıcıyla birleştirir. Tekrar sayısı 1–1.000 ile sınırlıdır. Boyut denetimi girdi uzunluğu × sayıyı hesaplar; ayırıcının uzunluğunu katmaz.", useCase: "Tekrarlanabilir test kalıbı veya ayraçlı örnek oluşturun. Girdi ha, sayı 3 ve ayırıcı - olduğunda sonuç ha-ha-ha olur.", troubleshooting: "Sonuç beklenenden farklıysa sayı ve ayırıcıyı kontrol edin. 1.000 üzeri sayılar sınırlanır; yinelenen girdi 1.000.000 birimi aşarsa hata çıkar. Uzun bir ayırıcı son çıktıyı daha da uzatabilir.", faqQuestion: "Tam çıktı her zaman 1.000.000 karakterle sınırlı mı?", faqAnswer: "Denetim, girdi uzunluğu × sayı 1.000.000’i aşarsa işlemi durdurur. Ayırıcı bu hesaba katılmaz; uzun ayırıcı birleştirilmiş çıktının bu değeri aşmasına yol açabilir." } });
Object.assign(copy.pl, { "text-repeater": { principle: "Powtarza tekst wejściowy całkowitą liczbę razy i łączy kopie wybranym separatorem. Liczba powtórzeń jest ograniczona do 1–1 000. Kontrola rozmiaru oblicza długość wejścia × liczbę, bez długości separatora.", useCase: "Utwórz powtarzalny wzorzec testowy lub próbkę z separatorami. Dla tekstu ha, liczby 3 i separatora - wynikiem jest ha-ha-ha.", troubleshooting: "Jeśli wynik jest inny, sprawdź liczbę powtórzeń i separator. Wartości powyżej 1 000 są ograniczane; powtarzany tekst ponad 1 000 000 jednostek powoduje błąd. Długi separator dodatkowo zwiększy wynik.", faqQuestion: "Czy cały wynik zawsze mieści się w limicie 1 000 000 znaków?", faqAnswer: "Kontrola blokuje długość tekstu wejściowego × liczbę powtórzeń powyżej 1 000 000. Separator nie jest wliczany, więc długi separator może sprawić, że wynik końcowy przekroczy tę wartość." } });
Object.assign(copy.fil, { "text-repeater": { principle: "Umuulit ang input string nang buong bilang ng beses at pinagdurugtong ang mga kopya gamit ang napiling separator. Nililimitahan ang bilang sa 1–1,000. Input length × count ang sinusuri sa size check; hindi kasama ang haba ng separator.", useCase: "Gumawa ng nauulit na test pattern o sample na may delimiter. Sa input na ha, bilang na 3, at separator na -, ang output ay ha-ha-ha.", troubleshooting: "Tingnan ang bilang at separator kung iba ang resulta. Nililimitahan ang lampas 1,000; magbibigay ng error kung lampas 1,000,000 unit ang inuulit na input. Maaari pang pahabain ng mahabang separator ang final output.", faqQuestion: "Palaging hanggang 1,000,000 character lang ba ang buong output?", faqAnswer: "Hinaharang ng check ang input length × count na lampas 1,000,000. Hindi kasama ang separator sa kalkulasyon, kaya maaaring lumampas dito ang pinagdugtong na resulta kapag mahaba ang separator." } });
Object.assign(copy.bn, { "text-repeater": { principle: "ইনপুট স্ট্রিংকে পূর্ণসংখ্যা বার পুনরাবৃত্তি করে নির্বাচিত বিভাজক দিয়ে কপিগুলো জোড়ে। সংখ্যা ১–১,০০০-এ সীমিত। আকার পরীক্ষা ইনপুটের দৈর্ঘ্য×সংখ্যা দেখে; বিভাজকের দৈর্ঘ্য এতে ধরা হয় না।", useCase: "পুনরাবৃত্ত পরীক্ষার নমুনা বা বিভাজকযুক্ত লেখা তৈরি করুন। ha ইনপুট, সংখ্যা ৩ এবং - বিভাজকে ফল হবে ha-ha-ha।", troubleshooting: "ফল আলাদা হলে সংখ্যা ও বিভাজক পরীক্ষা করুন। ১,০০০-এর বেশি সংখ্যা সীমিত হয়; পুনরাবৃত্ত ইনপুট ১,০০০,০০০ একক ছাড়ালে ত্রুটি হয়। লম্বা বিভাজক চূড়ান্ত ফলকে আরও বড় করতে পারে।", faqQuestion: "সম্পূর্ণ ফল কি সব সময় ১,০০০,০০০ অক্ষরের মধ্যে থাকে?", faqAnswer: "ইনপুটের দৈর্ঘ্য×সংখ্যা ১,০০০,০০০ ছাড়ালে পরীক্ষা থামায়। বিভাজকের দৈর্ঘ্য হিসাবের অংশ নয়, তাই লম্বা বিভাজকে জোড়া ফল এই সংখ্যার বেশি হতে পারে।" } });
Object.assign(copy.uk, { "text-repeater": { principle: "Повторює вхідний рядок цілу кількість разів і з’єднує копії вибраним роздільником. Кількість обмежена 1–1 000. Перевірка розміру множить довжину вводу на кількість і не враховує роздільник.", useCase: "Створіть повторюваний тестовий шаблон або зразок із роздільниками. Для вводу ha, кількості 3 і роздільника - результат буде ha-ha-ha.", troubleshooting: "Якщо результат неочікуваний, перевірте кількість і роздільник. Значення понад 1 000 обмежуються; повторений текст довший за 1 000 000 одиниць спричинить помилку. Довгий роздільник додатково збільшить результат.", faqQuestion: "Чи весь результат завжди обмежений 1 000 000 символів?", faqAnswer: "Перевірка відхиляє довжину вводу × кількість понад 1 000 000. Роздільник до розрахунку не входить, тому довгий роздільник може збільшити фінальний результат понад це значення." } });
Object.assign(copy.ms, { "text-repeater": { principle: "Mengulang rentetan input sebanyak bilangan bulat dan mencantumkan salinan dengan pemisah pilihan. Bilangan dihadkan kepada 1–1,000. Semakan saiz mengira panjang input × bilangan; panjang pemisah tidak termasuk.", useCase: "Bina corak ujian berulang atau sampel dengan pemisah. Dengan input ha, bilangan 3 dan pemisah -, hasilnya ha-ha-ha.", troubleshooting: "Semak bilangan dan pemisah jika hasil berbeza. Bilangan melebihi 1,000 dihadkan; teks berulang melebihi 1,000,000 unit menyebabkan ralat. Pemisah panjang boleh memanjangkan hasil akhir.", faqQuestion: "Adakah keseluruhan hasil sentiasa terhad kepada 1,000,000 aksara?", faqAnswer: "Semakan menolak panjang input × bilangan yang melebihi 1,000,000. Pemisah tidak dikira, jadi pemisah panjang boleh menjadikan hasil cantuman melebihi angka itu." } });
Object.assign(copy.sv, { "text-repeater": { principle: "Upprepar indatasträngen ett helt antal gånger och sammanfogar kopiorna med den valda avgränsaren. Antalet begränsas till 1–1 000. Storlekskontrollen räknar indatalängd × antal; avgränsarens längd ingår inte.", useCase: "Skapa ett upprepningsbart testmönster eller ett exempel med avgränsare. Med ha, antal 3 och avgränsaren - blir resultatet ha-ha-ha.", troubleshooting: "Kontrollera antal och avgränsare om resultatet avviker. Antal över 1 000 begränsas; upprepad indatatext över 1 000 000 enheter ger fel. En lång avgränsare kan göra slutresultatet ännu längre.", faqQuestion: "Är hela resultatet alltid begränsat till 1 000 000 tecken?", faqAnswer: "Kontrollen stoppar indatalängd × antal över 1 000 000. Avgränsaren räknas inte med, så en lång avgränsare kan göra den sammanfogade texten längre än så." } });
Object.assign(copy.cs, { "text-repeater": { principle: "Opakuje vstupní řetězec celočíselný početkrát a kopie spojí zvoleným oddělovačem. Počet je omezen na 1–1 000. Kontrola velikosti počítá délku vstupu × počet, nikoli délku oddělovače.", useCase: "Vytvořte opakovatelný testovací vzor nebo ukázku s oddělovači. Pro vstup ha, počet 3 a oddělovač - vznikne ha-ha-ha.", troubleshooting: "Pokud výsledek neodpovídá očekávání, zkontrolujte počet a oddělovač. Hodnoty nad 1 000 se omezí; opakovaný text delší než 1 000 000 jednotek vyvolá chybu. Dlouhý oddělovač může výstup dále prodloužit.", faqQuestion: "Je celý výsledek vždy omezen na 1 000 000 znaků?", faqAnswer: "Kontrola odmítne délku vstupu × počet nad 1 000 000. Oddělovač do výpočtu nezahrnuje, takže dlouhý oddělovač může výsledný spojený text prodloužit nad tento limit." } });
Object.assign(copy.ro, { "text-repeater": { principle: "Repetă șirul de intrare de un număr întreg de ori și unește copiile cu separatorul ales. Numărul este limitat la 1–1.000. Verificarea calculează lungimea intrării × numărul, fără lungimea separatorului.", useCase: "Creează un model de test repetabil sau un exemplu cu delimitatori. Pentru intrarea ha, numărul 3 și separatorul -, rezultatul este ha-ha-ha.", troubleshooting: "Verifică numărul și separatorul dacă rezultatul diferă. Valorile peste 1.000 sunt limitate; textul repetat care depășește 1.000.000 de unități produce o eroare. Un separator lung poate mări și mai mult rezultatul final.", faqQuestion: "Rezultatul complet este întotdeauna limitat la 1.000.000 de caractere?", faqAnswer: "Verificarea respinge lungimea intrării × numărul peste 1.000.000. Separatorul nu intră în calcul, astfel unul lung poate face rezultatul concatenat să depășească această valoare." } });
Object.assign(copy.el, { "text-repeater": { principle: "Επαναλαμβάνει τη συμβολοσειρά εισόδου ακέραιο αριθμό φορών και ενώνει τα αντίγραφα με τον επιλεγμένο διαχωριστή. Ο αριθμός περιορίζεται σε 1–1.000. Ο έλεγχος μεγέθους υπολογίζει μήκος εισόδου × πλήθος, χωρίς το μήκος του διαχωριστή.", useCase: "Δημιουργήστε επαναλαμβανόμενο μοτίβο δοκιμής ή δείγμα με διαχωριστικά. Με είσοδο ha, πλήθος 3 και διαχωριστή -, το αποτέλεσμα είναι ha-ha-ha.", troubleshooting: "Ελέγξτε το πλήθος και τον διαχωριστή αν το αποτέλεσμα διαφέρει. Τιμές πάνω από 1.000 περιορίζονται· επαναλαμβανόμενο κείμενο πάνω από 1.000.000 μονάδες προκαλεί σφάλμα. Μεγάλος διαχωριστής μπορεί να αυξήσει κι άλλο το τελικό αποτέλεσμα.", faqQuestion: "Περιορίζεται πάντα όλο το αποτέλεσμα σε 1.000.000 χαρακτήρες;", faqAnswer: "Ο έλεγχος απορρίπτει μήκος εισόδου × πλήθος πάνω από 1.000.000. Δεν συνυπολογίζει τον διαχωριστή, οπότε ένας μεγάλος διαχωριστής μπορεί να κάνει το ενωμένο αποτέλεσμα μεγαλύτερο." } });

// Locale-aware line sorting editorial. The processor compares with numeric
// ordering and base sensitivity, then reverses the comparison for descending mode.
Object.assign(copy.ko, { "sort-lines": { principle: "각 줄을 지정된 언어 규칙에 따라 비교해 오름차순으로 다시 배열합니다. 숫자가 포함된 항목은 수치 순서로 비교하고 대소문자 차이는 같은 기본 문자로 취급합니다.", useCase: "이름 목록이나 버전 목록을 정리할 때 유용합니다. `item10`, `item2`, `item1`은 숫자 정렬로 `item1`, `item2`, `item10` 순서가 됩니다.", troubleshooting: "줄 앞뒤 공백은 자동으로 제거되지 않으므로 정렬이 예상과 다르면 공백과 선택한 언어를 확인하세요. 빈 줄도 하나의 항목이며, 내림차순 옵션은 비교 순서만 뒤집습니다.", faqQuestion: "숫자가 들어간 줄도 사전식으로 정렬되나요?", faqAnswer: "아니요. 숫자 정렬을 사용하므로 `item2`가 `item10`보다 먼저 옵니다. 비교는 선택한 locale의 규칙을 따르며, 대소문자만 다른 항목은 같은 기본 수준으로 비교됩니다." } });
Object.assign(copy.en, { "sort-lines": { principle: "Compares each line using the selected locale and returns them in ascending order. Numeric portions are compared by value, while letter case is treated as a base-level difference.", useCase: "Use it to organize names or version labels. With numeric sorting, `item10`, `item2`, `item1` becomes `item1`, `item2`, `item10`.", troubleshooting: "Leading and trailing spaces are not trimmed, so inspect whitespace and the selected locale when the order looks unexpected. Blank lines are entries too; descending mode simply reverses the comparison.", faqQuestion: "Are lines containing numbers sorted lexically?", faqAnswer: "No. Numeric comparison puts `item2` before `item10`. Ordering follows the selected locale, and strings that differ only by letter case compare at the same base sensitivity." } });
Object.assign(copy.ja, { "sort-lines": { principle: "各行を選択した言語の照合規則で比較し、昇順に並べ替えます。数字を含む部分は数値として比較し、大文字と小文字の違いは基本的な比較では区別しません。", useCase: "名前やバージョンの一覧整理に使えます。数値順では `item10`、`item2`、`item1` が `item1`、`item2`、`item10` になります。", troubleshooting: "行頭・行末の空白は削除されません。順序が想定と違う場合は空白と選択中の言語を確認してください。空行も項目として扱い、降順は比較順を反転します。", faqQuestion: "数字を含む行も文字列順で並びますか？", faqAnswer: "いいえ。数値比較により `item2` は `item10` より前になります。選択した言語の規則で比較し、大文字小文字だけが異なる文字列は基本感度で同等に扱います。" } });
Object.assign(copy.zh, { "sort-lines": { principle: "按所选语言的排序规则比较每一行，并按升序排列。数字部分按数值比较；在基础比较级别上，大小写差异不区分。", useCase: "可用于整理姓名或版本列表。启用数字排序后，`item10`、`item2`、`item1` 会变成 `item1`、`item2`、`item10`。", troubleshooting: "行首和行尾空格不会自动删除。顺序不符合预期时，请检查空格和所选语言。空行也会作为条目处理；降序选项会反转比较顺序。", faqQuestion: "含数字的行会按普通字符串顺序排列吗？", faqAnswer: "不会。数值比较会让 `item2` 排在 `item10` 前面。排序遵循所选语言规则，仅大小写不同的字符串在基础比较级别视为相同。" } });
Object.assign(copy.es, { "sort-lines": { principle: "Compara cada línea según la configuración regional elegida y las devuelve en orden ascendente. Las partes numéricas se comparan por valor y las diferencias de mayúsculas se ignoran en el nivel básico.", useCase: "Ordena listas de nombres o versiones. Con comparación numérica, `item10`, `item2`, `item1` queda como `item1`, `item2`, `item10`.", troubleshooting: "No se eliminan los espacios al inicio o al final; revisa los espacios y el idioma si el orden sorprende. Las líneas vacías también cuentan como elementos; el modo descendente invierte la comparación.", faqQuestion: "¿Las líneas con números se ordenan como texto normal?", faqAnswer: "No. La comparación numérica coloca `item2` antes de `item10`. Se aplican las reglas del idioma elegido y las cadenas que solo difieren en mayúsculas se consideran iguales en el nivel básico." } });
Object.assign(copy["pt-br"], { "sort-lines": { principle: "Compara cada linha conforme a localidade escolhida e as organiza em ordem crescente. Partes numéricas são comparadas pelo valor; diferenças entre maiúsculas e minúsculas não contam no nível básico.", useCase: "Organize listas de nomes ou versões. Com comparação numérica, `item10`, `item2`, `item1` passa a `item1`, `item2`, `item10`.", troubleshooting: "Espaços no início ou no fim não são removidos. Se a ordem parecer estranha, confira os espaços e a localidade selecionada. Linhas vazias também são itens; a ordem decrescente apenas inverte a comparação.", faqQuestion: "Linhas com números são ordenadas como texto comum?", faqAnswer: "Não. A comparação numérica coloca `item2` antes de `item10`. A ferramenta segue a localidade escolhida e trata textos que diferem apenas por maiúsculas no mesmo nível básico." } });
Object.assign(copy.de, { "sort-lines": { principle: "Vergleicht jede Zeile nach der gewählten Spracheinstellung und gibt sie aufsteigend zurück. Zahlenteile werden nach ihrem Wert verglichen; Groß- und Kleinschreibung zählt auf der Basisebene nicht.", useCase: "Ordnen Sie Namens- oder Versionslisten. Bei numerischem Vergleich wird aus `item10`, `item2`, `item1` die Reihenfolge `item1`, `item2`, `item10`.", troubleshooting: "Leerzeichen am Zeilenanfang und -ende werden nicht entfernt. Prüfen Sie bei unerwarteter Reihenfolge Leerzeichen und Spracheinstellung. Leere Zeilen zählen mit; absteigend kehrt den Vergleich um.", faqQuestion: "Werden Zeilen mit Zahlen lexikografisch sortiert?", faqAnswer: "Nein. Der Zahlenvergleich setzt `item2` vor `item10`. Es gelten die Regeln der gewählten Sprache; Zeichenfolgen, die sich nur durch Groß- und Kleinschreibung unterscheiden, gelten auf Basisebene als gleich." } });
Object.assign(copy.fr, { "sort-lines": { principle: "Compare chaque ligne selon la langue choisie et les renvoie par ordre croissant. Les parties numériques sont comparées par valeur ; la casse n'est pas prise en compte au niveau de sensibilité de base.", useCase: "Triez des listes de noms ou de versions. Avec le tri numérique, `item10`, `item2`, `item1` devient `item1`, `item2`, `item10`.", troubleshooting: "Les espaces en début et en fin de ligne ne sont pas supprimés. Vérifiez-les ainsi que la langue si l'ordre vous surprend. Les lignes vides comptent aussi ; le mode décroissant inverse la comparaison.", faqQuestion: "Les lignes contenant des chiffres sont-elles triées comme du texte brut ?", faqAnswer: "Non. La comparaison numérique place `item2` avant `item10`. Le tri suit la langue choisie et considère comme équivalentes au niveau de base les chaînes qui ne diffèrent que par la casse." } });
Object.assign(copy.vi, { "sort-lines": { principle: "So sánh từng dòng theo ngôn ngữ đã chọn rồi sắp xếp tăng dần. Phần số được so sánh theo giá trị; khác biệt chữ hoa và chữ thường không được tính ở mức cơ bản.", useCase: "Dùng để sắp xếp danh sách tên hoặc phiên bản. Với so sánh số, `item10`, `item2`, `item1` thành `item1`, `item2`, `item10`.", troubleshooting: "Khoảng trắng đầu và cuối dòng không bị xóa. Nếu thứ tự lạ, hãy kiểm tra khoảng trắng và ngôn ngữ đang chọn. Dòng trống cũng là một mục; chế độ giảm dần chỉ đảo chiều so sánh.", faqQuestion: "Dòng có số được sắp theo thứ tự chuỗi thông thường không?", faqAnswer: "Không. So sánh số đặt `item2` trước `item10`. Quy tắc của ngôn ngữ đã chọn được áp dụng; chuỗi chỉ khác chữ hoa hay chữ thường được xem như nhau ở mức cơ bản." } });
Object.assign(copy.id, { "sort-lines": { principle: "Membandingkan setiap baris menurut locale yang dipilih lalu mengurutkannya secara menaik. Bagian angka dibandingkan berdasarkan nilainya; perbedaan huruf besar dan kecil diabaikan pada tingkat dasar.", useCase: "Rapikan daftar nama atau versi. Dengan perbandingan numerik, `item10`, `item2`, `item1` menjadi `item1`, `item2`, `item10`.", troubleshooting: "Spasi di awal dan akhir baris tidak dihapus. Jika urutan terasa janggal, periksa spasi dan locale pilihan. Baris kosong tetap dihitung sebagai item; mode menurun hanya membalik urutan perbandingan.", faqQuestion: "Apakah baris yang berisi angka diurutkan secara leksikografis?", faqAnswer: "Tidak. Perbandingan numerik menempatkan `item2` sebelum `item10`. Aturan locale pilihan digunakan, dan teks yang hanya berbeda kapitalisasi dianggap setara pada tingkat dasar." } });
Object.assign(copy.th, { "sort-lines": { principle: "เปรียบเทียบแต่ละบรรทัดตามภาษาที่เลือกแล้วเรียงจากน้อยไปมาก ส่วนตัวเลขจะเทียบตามค่า และไม่แยกตัวพิมพ์ใหญ่กับตัวพิมพ์เล็กในระดับพื้นฐาน", useCase: "ใช้จัดรายการชื่อหรือเวอร์ชัน เมื่อเทียบตัวเลข `item10`, `item2`, `item1` จะเรียงเป็น `item1`, `item2`, `item10`", troubleshooting: "ช่องว่างต้นและท้ายบรรทัดจะไม่ถูกลบ หากลำดับไม่ตรงคาดให้ตรวจช่องว่างและภาษาที่เลือก บรรทัดว่างนับเป็นรายการด้วย ส่วนโหมดจากมากไปน้อยจะกลับลำดับการเปรียบเทียบ", faqQuestion: "บรรทัดที่มีตัวเลขเรียงแบบข้อความทั่วไปหรือไม่", faqAnswer: "ไม่ใช่ การเทียบตัวเลขจะวาง `item2` ก่อน `item10` โดยใช้กฎของภาษาที่เลือก และข้อความที่ต่างกันเพียงตัวพิมพ์ใหญ่เล็กจะถือว่าเท่ากันในระดับพื้นฐาน" } });
Object.assign(copy["zh-tw"], { "sort-lines": { principle: "依照所選語言的排序規則比較每一行，並以升冪排列。數字部分依數值比較；在基本比較層級中不區分大小寫。", useCase: "可整理姓名或版本清單。使用數字比較時，`item10`、`item2`、`item1` 會排列為 `item1`、`item2`、`item10`。", troubleshooting: "不會自動移除行首或行尾空白。順序不如預期時，請檢查空白與所選語言。空白行也會視為項目；降冪模式只會反轉比較順序。", faqQuestion: "含數字的行會依一般字串順序排列嗎？", faqAnswer: "不會。數值比較會讓 `item2` 排在 `item10` 前面。排序遵循所選語言規則，只有大小寫不同的字串在基本比較層級會視為相同。" } });
Object.assign(copy.it, { "sort-lines": { principle: "Confronta ogni riga secondo la lingua selezionata e la restituisce in ordine crescente. Le parti numeriche vengono confrontate per valore; maiuscole e minuscole non si distinguono al livello di base.", useCase: "Riordina elenchi di nomi o versioni. Con il confronto numerico, `item10`, `item2`, `item1` diventa `item1`, `item2`, `item10`.", troubleshooting: "Gli spazi iniziali e finali non vengono rimossi. Se l'ordine sorprende, controlla gli spazi e la lingua selezionata. Anche le righe vuote sono elementi; la modalità decrescente inverte il confronto.", faqQuestion: "Le righe con numeri vengono ordinate come testo normale?", faqAnswer: "No. Il confronto numerico colloca `item2` prima di `item10`. Si applicano le regole della lingua scelta e le stringhe che differiscono solo per maiuscole o minuscole sono equivalenti al livello di base." } });
Object.assign(copy.nl, { "sort-lines": { principle: "Vergelijkt elke regel volgens de gekozen taalinstelling en geeft de regels oplopend terug. Getallen worden op waarde vergeleken; hoofdlettergebruik telt niet mee op het basisniveau.", useCase: "Sorteer namen of versielabels. Met numerieke vergelijking wordt `item10`, `item2`, `item1` gerangschikt als `item1`, `item2`, `item10`.", troubleshooting: "Spaties aan het begin en einde worden niet verwijderd. Controleer die spaties en de gekozen taal als de volgorde onverwacht is. Lege regels tellen ook mee; aflopend keert de vergelijking om.", faqQuestion: "Worden regels met cijfers lexicografisch gesorteerd?", faqAnswer: "Nee. Numerieke vergelijking plaatst `item2` vóór `item10`. De gekozen taal bepaalt de sortering; tekst die alleen in hoofdletters verschilt, geldt op basisniveau als gelijk." } });
